quests[28490] = { id = 28490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Darkshore!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Priestess Dentaria at Lor'danel in Darkshore.\n\nThe people of Lor'danel need your aid in caring for the survivors of Auberdine's destruction and securing their town against Twilight's Hammer. Speak to Vesprystus, the hippogryph master at Rut'theran Village outside of Darnassus and he'll arrange a flight to Darkshore.\n\nFor the glory and honor of the Alliance!", completion = "So, the king has heard our plea? Thank Elune! We can use all the help we can get.", objectives = "Report to Priestess Dentaria at Lor'danel in Darkshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28491] = { id = 28491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Fireflies, Flameflies", description = "Most of my fellow residents here at Flame Crest seem to have left at some point.  I guess the Burning Steppes weren't INTERESTING enough for them.\n\nNot me, though.  I'm always finding new reasons to not leave, and the latest happens to be the flameflies that have been appearing lately.\n\nThey appear near lava during the day.  By night, you'll find them almost anywhere.\n\nIf you wouldn't mind collecting some, I might be able to make it worth your while.", progress = "Well?", completion = "Nice work!  More pets for Kibler!", objectives = "Gather 7 Flameflies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28492] = { id = 28492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Ashenvale!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Sentinel Shyela at Orendil's Retreat in northwestern Ashenvale.\n\nThe Horde's aggression in Ashenvale cannot be allowed to stand! Your help is needed to repel the invaders and restore the sacred forest. Head south through the Twilight Vale in Darkshore to reach the forest of Ashenvale.\n\nFor the glory and honor of the Alliance!", completion = "Have you come to help us fight back against the forces of the Horde? Every blade and spell will be needed!", objectives = "Report to Sentinel Shyela at Ordanil's Retreat in northwestern Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28493] = { id = 28493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Ashenvale!", description = "All able bodied members of the Horde are hereby ordered to report to Kadrak at the Mor'shan Rampart on the border between the Northern Barrens and Ashenvale. Aid in driving the night elves from the forest, so that we may claim its resources for our people!\n\nTo reach the Mor'shan Rampart, you must take the Gold Road north from Crossroads in the Northern Barrens.\n\nDestiny calls!", completion = "So you're the reinforcements? I suppose you'll do fine as long you can kill night elves.", objectives = "Report to Kadrak at the Mor'shan Rampart on the border between the Northern Barrens and Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28494] = { id = 28494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Northern Barrens!", description = "All able-bodied members of the Horde are hereby ordered to report to Kargal Battlescar at Far Watch Post in the Northern Barrens.\n\nYour help is needed to secure the Northern Barrens against the encroaching quilboars and centaurs.\n\nTo reach Far Watch Post, travel west across Durotar's Southfury Watershed and cross the bridge into the Northern Barrens.\n\nDestiny calls!", completion = "You look competent with a weapon or a spellbook. We could use your help in driving back the quillboars in these parts.", objectives = "Report to Kargal Battlescar at Far Watch Post in the Northern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28495] = { id = 28495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fighting Chance", description = "Blessed be the Light! I need your help!\n\nOn my way into Hillsbrad I noticed several families of adorable little deer. As I went out to pet one of the little fawns a ravenous mountain cat leapt out and killed it. I fled to Tarren Mill and swore to solve the plight of the hill fawn. Now, after many days of tinkering, I have created the hill fawn's salvation!\n\nTake my wand into the fields to the west and use it to empower the wee hill fawns. Once empowered they will be able to fend for themselves!", completion = "WHAT!? No, don't tell me that, {name}! It can't be true! My... I... I would never...\n\nI won't give up, {class}. Just you wait and see. I will save those fawns!", objectives = "Save 10 Hill Fawns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28496] = { id = 28496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Azshara!", description = "All able-bodied members of the Horde are hereby ordered to report to Ag'tor Bloodfist at the Orgrimmar Rear Gate in Azshara.\n\nAid in driving back the encroaching Alliance forces and assist in securing Azshara for the glory of the Horde!\n\nDepart Orgrimmar through its northern gate to reach the Orgrimmar Rear Gate in Azshara.\n\nDestiny calls!", completion = "We could sure use some help out here.", objectives = "Report to Labor Captain Grabbit at the Orgrimmar Rear Gate in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28497] = { id = 28497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire From the Sky", description = "Sullah wasn't kidding. That hill is crawling with troopers!\n\nJump on and paint our targets for me.\n\nMake every shot count, {name}! We need to be able to get up there.", progress = "Don't think twice, {name}.\n\nThese guys are rotten to the core.", completion = "Good work, {name}.\n\nNow let's see if we can make our way up there before they're able to recover.", objectives = "Kill 100 Schnottz Troopers while mounted on the Confiscated Artillery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28498] = { id = 28498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secret of Nahom", description = "There is an old story about Nahom.  It speaks of how a powerful prophet named Atulhet held off troves of enemies by channeling the power of the sun through this very temple.\n\nMost believe the tale to be just a legend, but that power... would certainly be useful to us now.\n\nThe vile Neferset have ransacked Atulhet's tomb.  They've taken any artifacts of power and shattered the tablets that encode his memories.\n\nGo to the Tombs of the Precursors to the east and retrieve any fragments that you find.", progress = "Did you find them, {name}?  Were they salvageable?", completion = "Excellent.  Let's see if we can find anything of importance.", objectives = "Obtain 8 Atulhet's Record Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28499] = { id = 28499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Punish the Trespassers", description = "We, priests of Nahom, are guardians of the Tombs of the Precursors.\n\nEver since the Neferset turned to their new masters, they've turned to great heresies.\n\nThey rob the sacred tombs of our forefathers, seeking powerful artifacts and destroying invaluable relics in the process.\n\nGo to the tombs, east of here and punish the tomb-robbers for their transgressions, lest they join their brethren when the Neferset attack on Nahom begins.", progress = "You're back, {name}.  Is your prowess as great as I've heard?", completion = "Perhaps you are as powerful as I've heard afterall.\n\nYou have our gratitude.", objectives = "Slay any 10 Neferset intruders at the Tombs of the Precursors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28500] = { id = 28500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cypher of Keset", description = "<Salhet spends some time going over the tablets with the priests around him.>\n\nIt's all right here, {name}.  Atulhet built a potent weapon into this temple and the only way to access it is with the correct cypher.\n\nIt is reportedly hidden in the Keset Pass.  We must hope the Neferset looters haven't gotten to it yet.  That's where Raider Lord Havat is operating and he's the most ruthless of the lot.\n\nBut without reinforcements, this might be our only hope for defending Nahom.", progress = "Did you retrieve the codex, {name}?", completion = "It is true then?  It does exist!", objectives = "Obtain the Cypher of Keset.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28501] = { id = 28501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defense of Nahom", description = "The enemy is coming... and in great numbers.\n\nWe will get no further reinforcements.  Let us hope we can stop the Neferset advance.\n\nIf Nahom falls, Ramkahen will follow.\n\nGo outside and speak to one of my sergeants when you're ready.  I will help you command the forces we have to the best of my ability.", progress = "There is no time to waste!", completion = "We did it, {name}!  We held Nahom.", objectives = "Speak to a Ramkahen Sergeant and succeed in the Defense of Nahom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28502] = { id = 28502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bandit Warlord", description = "Our law demands that those behind this attack face proper retribution.\n\nThe band of bandits' ringleader is a man known as Warlord Ihsenn.\n\nYou will find him in the far west of the desert.  Make sure his transgressions do not go unpunished.", completion = "I thank you, {name}.  These savages must be punished for what they've done here.", objectives = "Slay Warlord Ihsenn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28503] = { id = 28503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Thousand Needles!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Caryssia Moonhunter at New Thalanaar at the border between Feralas and Thousand Needles.\n\nThe sentinels need your help to turn back the marauding Grimtotem raiders who dominate the area. To reach New Thalaanar, travel to eastern Feralas, near the border with Thousand Needles.\n\nFor the glory and honor of the Alliance!", completion = "You've arrived just in time, {class}. We need your help to hold off the Grimtotem.", objectives = "Report to Caryssia Moonhunter at New Thalanaar on the border between Feralas and Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28504] = { id = 28504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Thousand Needles!", description = "All able bodied members of the Horde are hereby ordered to report to Nyse at Mudsprocket. Join the Horde forces fighting against the renegade Grimtotems who dominate the area.\n\nNyse will provide you with transportation to the front lines. She will be waiting for you at Mudsprocket's inn, tucked away in southern Dustwallow Marsh.\n\nDestiny calls!", progress = "Oh good, you are here.", completion = "The Horde forces in Thousand Needles desperately need your help.", objectives = "Report to Nyse at Mudsprocket in southern Dustwallow Marsh. Optionally, grab a flight there from Doras in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28505] = { id = 28505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Andorhal", description = "I just got word, <lad/lass>.  It doesn't sound good.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  King Wrynn has rolled the dice and sent a death knight to lead the charge for his cause, but I'm sure he can use all the help he can get.\n\nI hate to see you go, but they've asked for you by name, {name}.  Speak with Guthrum Thunderfist outside.  He'll put you on the first gryphon out to Andorhal.", completion = "It's about time you arrived, {class}.", objectives = "Speak with Guthrum Thunderfist to fly to Andorhal in Western Plaguelands. Then report to Thassarian within Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28506] = { id = 28506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "March of the Stormpike", description = "These plans you recovered weave an interesting tale, {name}. The Stormpike have been moving their armies from Alterac Valley into the \"four fingers\" of Hillsbrad for over a month. Somehow they have managed to secretly get their installations set up without our forces knowing. Had we not received these plans they would have marched on us in a week's time, annihilating everything in their path.\n\nWith these plans, though, we can turn the tables.\n\nThis is what we must do...", completion = "The time to act is now. The Stormpike must be crushed!", objectives = "See the March of the Stormpike.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28507] = { id = 28507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Tanaris!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Kelsey Steelspark in Gadgetzan.\n\nThe Alliance needs your help to win concessions from the local baron and access to the area's priceless resources. You can reach Gadgetzan by traveling south from the Shimmering Deep in Thousand Needles.\n\nFor the glory and honor of the Alliance!", completion = "We have to persuade the goblins of Gadgetzan to side with us, {class}.", objectives = "Report to Kelsey Steelspark at Gadgetzan in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28508] = { id = 28508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Andorhal", description = "I just received the most curious missive.  Curious indeed...\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  It sounds like Sylvanas has made her move, and to make matters interesting, she's put Koltira Deathweaver, the death knight, in command.\n\nThey've asked for you by name, {name}.  Speak with Kellen Kuhn, the bat handler.  He'll put you on the first bat out to Andorhal.", completion = "It's about time you arrived, {class}.", objectives = "Speak with Kellen Kuhn to fly to Andorhal in Western Plaguelands. Then report to Koltira Deathweaver within Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28509] = { id = 28509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Tanaris!", description = "All able bodied members of the Horde are hereby ordered to report to Megs Dreadshredder in Gadgetzan. Help the Horde and the Bilgewater Cartel establish a presence in Tanaris before the Alliance does!\n\nYou can reach Gadgetzan in Tanaris by traveling south to the shore from Fizzle and Pozzik's Speedbarge in southeastern Thousand Needles. Or, you can get a flight there from Doras in Orgrimmar.\n\nDestiny calls!", progress = "It's about time!", completion = "I could use your help, {class}. That blasted gnome is trying to persuade the Steemwheedle Cartel to favor her side!", objectives = "Report to Megs Dreadshredder at Gadgetzan in Tanaris. Optionally, grab a flight there from Doras in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28510] = { id = 28510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Feralas!", description = "All able bodied members of the Horde are hereby ordered to report to Konu Runetotem at Camp Ataya in Feralas. Help the Horde secure the great forest against the Alliance and the Grimtotems.\n\nYou can reach Camp Ataya by traveling south from Desolace and into Feralas.\n\nDestiny calls!", completion = "There is much wrong in Feralas. I am glad to have your help.", objectives = "Report to Konu Runetotem at Camp Ataya in Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28511] = { id = 28511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Feralas!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Telaron Windflight at Dreamer's Rest in Feralas.\n\nThe Alliance needs your help to overcome our enemies, the Horde and the Grimtotems. You can reach Dreamer's Rest by traveling south from Desolace into Feralas.\n\nFor the glory and honor of the Alliance!", completion = "Elune has favored us with your arrival, {class}. There is much to do.", objectives = "Report to Telaron Windflight at Dreamer's Rest in Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28512] = { id = 28512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Aid of the Thorium Brotherhood", description = "Dark Iron dwarves may be scheming and mischievous... but they're not all enemies.  I've spoken several times with the dwarves of the Thorium Brotherhood, and they've never been anything but helpful.\n\nAn acquaintance of mine, Jack Rockleg, came to town not long ago, asking if I could join him on an expedition of some sort.  It sounded important.\n\nI'm a little busy, but maybe you wouldn't mind going?  Just travel west, on the road to Searing Gorge.  You'll see him soon after leaving the Badlands.", completion = "Well whadda we have here?  You here to help?", objectives = "Speak with Jack Rockleg at Thorium Advance in Searing Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28513] = { id = 28513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pride of the Highborne", description = "Ten thousand years ago...\n\nThe Highborne lived here in prosperity. We considered ourselves above the common ranks of the other night elves. With our every need met by magic and wealth, we led lives of indulgence and amusement. And greed...\n\nThe spirits you see here are overwhelmed with remorse and regret. Their anguish chains them here. If you wish to learn more of Kel'theril and Zin'malor, free them from their agony.", progress = "Death is not always a relief.", completion = "The Crystal of Zin-Malor was stolen from a far-off temple without remorse. Its ability to control the arcane was too tempting, and when it was toyed with, its shattering cursed us all. Kel'theril suffered until the Sundering destroyed it for good.\n\nThe curse of Zin-Malor binds all who seek its power here. I was the first to fall to its temptation. Thousands of years later, our long lost descendants would be next...", objectives = "Slay 8 Anguished or Suffering Highborne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28514] = { id = 28514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mouton Flamestar", description = "I get precious little time away from Searing Gorge these days.  I've been meaning to visit a friend in Burning Steppes for the last several months, but haven't had the chance.\n\nHis name is Mouton Flamestar.  While he's not a member of the Brotherhood, he's a trusted friend, and definitely trustworthy.\n\nWill you send him my regards?  You'll have to travel south, through the base of Blackrock Mountain.  Just keep heading south... you'll find him.\n\nThank you.", completion = "Oh, Oilfist sent you?  Hah!\n\nDid he ever tell you how he got the name Oilfist?  You'll have to ask him about that one sometime.", objectives = "Report to Mouton Flamestar at Flamestar Post in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28515] = { id = 28515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mouton Flamestar", description = "I get precious little time away from Searing Gorge these days.  I've been meaning to visit a friend in Burning Steppes for the last several months, but haven't had the chance.\n\nHis name is Mouton Flamestar.  While he's not a member of the Brotherhood, he's a trusted friend, and definitely trustworthy.\n\nWill you send him my regards?  You'll have to travel south, through the base of Blackrock Mountain.  Just keep heading south... you'll find him.\n\nThank you.", completion = "Oh, Oilfist sent you?  Hah!\n\nDid he ever tell you how he got the name Oilfist?  You'll have to ask him about that one sometime.", objectives = "Report to Mouton Flamestar at Flamestar Post in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28516] = { id = 28516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Centuries of Suffering", description = "I only agreed to even consider cooperating with night elves and the alliance on rumors that the Crystal of Zin-Malor was found here.\n\nThe crystal is a powerful and ancient artifact, whose destruction cursed this land, and whose reassembly has caused little relief.\n\nBut I cannot face the hauntings that dwell here. Mock me if you must, but if you do, try your own hand. Perhaps the placid spirits that sit at the center of the lake will speak with you...", sourceObjective = "Speak with the Kaldorei Spirit at the center of Lake Kel'theril.", sourceObjectiveStatus = "unverified-source-field" }
quests[28517] = { id = 28517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Howling Oak", description = "So this is it... our new home. I'm not sure if I'll ever feel like I truly have a home again.\n\nWe mustn't be unappreciative of what the night elves have offered us though. Their race is not one to throw out idle welcomes to just anyone. It is a true testament to faith and generosity that they've taken us in.\n\nGwen and Greymane are in the city proper, at the Howling Oak. You should stop by. Take the portal beneath the tree north of us, then seek out the Howling Oak in the northern portion of the city.", completion = "This oak was grown through the aid of the druids from a seed taken back on Gilneas. It stands for all that we've endured, and all that we've accomplished.\n\nMay it serve to remind us that our curse is also our blessing.", objectives = "Speak to Genn Greymane at the Howling Oak in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28518] = { id = 28518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of the High Elves", description = "One hundred years ago...\n\nI and a small group of other High Elves traveled here from our homeland, Quel'thalas. We sought the ancient mysteries of Kel'thoril... to find why it was destroyed.\n\nWe found fragments in the ice, shards of the crystal. The Archmage we accompanied did not take long to fall under their sway. In our foolishness, we noticed too late.\n\nHis spirit wanders in the southeast, among those he drove to madness, still clutching the memory of the precious shard...", progress = "Maenius was a powerful mage and an honorable elf.  His spirit did not deserve such an ignoble fate.", completion = "We were shocked before we died. Shocked that one among our noble and austere kind could descend into vicious obsession so quickly. We died as naive fools, the victims of our own blithe assumptions.\n\nThe living would know that these events would play out yet again... both here, and among the entire elven race with the fall of Quel'thalas.", objectives = "Obtain the Memory of Zin-Malor from the spirit of Archmage Maenius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28519] = { id = 28519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pain of the Blood Elves", description = "One year ago...\n\nThe legend of the Crystal of Zin-Malor reached Silvermoon, and I led a group of the finest warriors and scholars available to this land. We brought ample mana crystals, so none of us would be tempted to taste the crystal itself.\n\nThe crystal did not need our hunger to ruin us. Once in our possession, it warped all but me into wretched beasts.\n\nThe wretched souls still wander, seeking more lives to chain to this lake. Will you give them mercy... or flee to die on safer ground someday?", progress = "Do not loiter too long. There are few escapes from Kel'theril.", completion = "The living farstrider who sent you here could not bear to see our fate. He ran... a wise decision.\n\nIf one now holds the Crystal of Zin-Malor again, it will spell the doom of all around them. It should never have been reassembled.", objectives = "Slay 7 Wretched Spirits or Wretched Spectres at Lake Kel'theril.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28520] = { id = 28520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Neferset City", description = "We are ready to strike now, {name}.\n\nIf we take down Dark Pharaoh Tekahn, the immortal colossi will fall and our armies will be able to march into Neferset City.\n\nSeek him out and engage him without fear.  I will make sure you're not alone when it's time to bring him down.", completion = "It is done.  We have defeated the Neferset inside their own city.\n\nI wish I could say that there is peace for my people at last, but I only foresee more bloodshed.", objectives = "Slay Dark Pharaoh Tekahn at Neferset City in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28521] = { id = 28521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak to Salfa", description = "The threat of corruption comes not only from the Deadwood furbolgs to the south, but also from the east and the Winterfall furbolgs of Winterspring.  If you wish to further aid us, speak with Salfa on the other side of the Hold, by the Winterspring entrance.  Follow the path to the left to reach it.", completion = "Greetings, {class} - I stand guard here as both a speaker for the Timbermaw here in Winterspring and as a defender of the tribe.\n\nOur Winterfall brethren here in this frigid land have fallen under the same corruptive sway as the furbolg of Felwood.  If you've come here offering the Timbermaw furbolgs aid, then we are ready to accept such an offer.", objectives = "Travel through Timbermaw Hold and exit into Winterspring. Speak with Salfa, who stands guard outside the entrance to Timbermaw Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28522] = { id = 28522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterfall Activity", description = "The Timbermaw tend to stay to themselves, {name}.  While we do allow safe passage to those we trust, we try to avoid other furbolg tribes if at all possible.\n\nThe Winterfall tribe has become increasingly hostile towards us.  They seem to be in a state of rage, completely engulfed by their own fear and hatred of anything they do not understand.\n\nThe Winterfall carry spirit beads, which have clearly failed to protect them against corruption. Bring me 10 of these beads to show you have thinned their ranks.", progress = "We very much appreciate what you have done for the Timbermaw, {name}.  Your continued efforts will surely earn my tribe's trust and respect.", completion = "Thank you for what you have done, as saddening as it is.  Accept this as a token of thanks.\n\nI would ask of you to please continue helping us, {name}.  We have very few allies on which to call upon, and without your aid, the threats against my tribe would surely be too much for us to handle alone.", objectives = "Collect 10 Spirit Beads from Winterfall furbolg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28523] = { id = 28523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Beads for Salfa", progress = "You've certainly earned my trust, {name}, but you may need to continue to earn the trust of my untrusting tribe.  There is something you can do to earn that trust.\n\nThe Winterfall are known to carry spirit beads to ward against foul spirits.  These beads have clearly failed in their purpose, as the Winterfall themselves are the agents of corruption.  Bring to me these spirit beads from fallen Winterfall furbolgs; for every set of five you bring me, you will earn recognition amongst the Timbermaw.", completion = "Once again, you prove your honor to us!  I will make sure that your deeds are known amongst my kind.\n\nRemember to bring any of the Winterfall's beads you find to me.  For each set you continue to bring to me, I will speak on your behalf to the tribe." }
quests[28524] = { id = 28524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery for Donova", description = "Donova Snowden is a kind dwarf who frequents the nearby hot springs. She claims to be studying their magical properties.\n\nShe is a kind person and has good relations with our tribe. As the Winterfall have become more and more aggressive, she has begun researching the cause of their corruption.\n\nI must keep my post here, but I have made a basket of refreshments for her. Please take it to her for me and tell her we await her next visit.", progress = "Welcome to the hot springs. What've you got there?", completion = "Oh, how nice of those dear furbolg. I feel so bad for them, cooped up in that hold, afraid of the world.\n\nBut can you blame them? These Winterfall furbolg are turning just as vicious as any in Felwood. I'd like to put a stop to it... if only for the sake of my own research, let alone the dear Timbermaw.", objectives = "Deliver Salfa's Basket to Donova Snowden in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28525] = { id = 28525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Un'Goro Crater!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Williden Marshal at Marshal's Stand.\n\nThe Alliance needs you to provide support to the Marshal Expeditions as they uncover the secrets of Un'Goro Crater's ancient beasts, unique flora, and powerful crystals. You can reach the crater by departing western Tanaris and following the road all the way to Marshal's Stand.\n\nFor the glory and honor of the Alliance!", completion = "My team of explorers, researchers, and scientists is the finest in Azeroth, but we need all the help we can get to discover the truth about the crater's history and its denizens.", objectives = "Report to Williden Marshal at Marshal's Stand in Un'Goro Crater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28526] = { id = 28526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Un'Goro Crater!", description = "All able bodied members of the Horde are hereby ordered to report Williden Marshal at Marshal's Stand. You are to provide aid to the Marshal Expeditions' personnel as they uncover the secrets of Un'Goro Crater. The Horde may be able to find a use for the unique beasts and crystals populating the crater.\n\nYou can reach Un'Goro Crater by taking the road from western Tanaris down into the crater and toward Marshal's Stand. Or, you can get a flight there from Doras in Orgrimmar.\n\nDestiny calls!", progress = "Are you here to help?", completion = "Welcome, {class}. My scientists and explorers will be glad to have your help.", objectives = "Report to Williden Marshal at Marshal's Stand in Un'Goro Crater. Optionally, grab a flight there from Doras in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28527] = { id = 28527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Silithus!", description = "All able-bodied members of the Horde are hereby ordered to report to Windcaller Proudhorn at Cenarion Hold. You are to aid our Cenarion allies in their battle to turn back Twilight's Hammer. Cho'Gall's minions must not be allowed to dominate Silithus!\n\nYou can reach Silithus by taking the northwestern road out of Un'Goro Crater. Or, you can get a flight there from Doras in Orgrimmar.\n\nDestiny calls!", progress = "You look like help.", completion = "Welcome to Cenarion Hold.", objectives = "Report to Windcaller Proudhorn at Cenarion Hold in Silithus. Optionally, grab a flight there from Doras in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28528] = { id = 28528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Silithus!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Windcaller Proudhorn at Cenarion Hold.\n\nOur Cenarion Circle allies require your assistance to fight back against the Twilight's Hammer onslaught. You can reach Silithus by taking the northwestern road out of the Un'Goro Crater.\n\nFor the glory and honor of the Alliance!", completion = "Welcome to Cenarion Hold.", objectives = "Report to Windcaller Proudhorn at Cenarion Hold in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28529] = { id = 28529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Writings of the Void", description = "The scrolls are vague and appear to be a piece of a much larger puzzle, but if you are not mistaken, they seem to reveal some of the steps on the path to becoming a demon hunter.\n\nThe dark oaths and rituals necessary for becoming a demon hunter are frowned on by most of the night elves, so this is likely something they would be very interested in keeping quiet.\n\nRanger Glynda Nal'Shea will know what to do with these scrolls.", progress = "How can I help you, {class}?", completion = "Where did you find these?! You haven't shown them to anyone else, have you?\n\nI apologize. You took me off guard. Telarius was a very powerful Demon Hunter, but he was slain during a confrontation with the warden, Maeiv, many years ago. You are fortunate that his ghost was only a shade of his former power. I wonder how many have found their way to him in those ruins.\n\nI will see to it that these scrolls make their way to the high priestess immediately. Thank you, {name}.", objectives = "Bring the Writings of the Dark Herald to Ranger Glynda Nal'Shea at Lor'danel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28530] = { id = 28530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scalding Signs", description = "The cauldron looked like it contained concentrated material. If the Winterfall are diluting this stuff directly in the springs, contamination could build up over time... and then the dilution would be less and less effective.\n\nThe spring to the northeast has boiled over with elementals. I thought it was because of the cataclysm, but their appearance could be a reaction to this.\n\nCould you check them for corruption? Hunt a few and bring me any bits of green foreign material they leave behind.", progress = "What did you find?", completion = "That's quite a bit of it... the Winterfall are slipping further and further. And now we'll have to worry about the other wildlife as well, in time.", objectives = "Collect 7 pieces of Suspicious Green Sludge from Scalding Springsurges or Boiling Springbubbles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28531] = { id = 28531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Desolace!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Officer Jankie on the road into Desolace at Tethris Aran.\n\nThe brave soldiers of Nijel's Point are beset by demons and the armies of the Horde, and they need your help. To reach Desolace, travel south on the road from the Charred Vale in the Stonetalon Mountains.\n\nFor the glory and honor of the Alliance!", completion = "I can get you to Nijel's Point quickly! We need all the reinforcements we can get.", objectives = "Report to Officer Jankie at Tethris Aran in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28532] = { id = 28532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Stonetalon Mountains!", description = "All able bodied members of the Horde are hereby ordered to report to Blood Guard Aldo Rockrain at Silverwind Refuge in Ashenvale. The Horde forces in Stonetalon need your help to drive back the Alliance invaders and protect our people. The blood guard will direct you to the border of Stonetalon.\n\nTo reach Silverwind Refuge, travel into the heart of Ashenvale and join our forces by the lake.\n\nDestiny calls!", completion = "So you're to deploy to Stonetalon? Good, we'll need your abilities to defeat the Alliance there.", objectives = "Report to Blood Guard Aldo Rockrain at Silverwind Refuge in Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28533] = { id = 28533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Council's Decision", description = "The High Council is ready to decide on the war with the Neferset tribe.", completion = "Very well, it looks like it's time.  Stay and watch if you so please.", objectives = "Speak to King Phaoris at Ramkahen in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28534] = { id = 28534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Descendants of the Highborne", description = "Not long after my death, the greed of my people would lead to their exile. A continent away, they would become Quel'dorei, the High Elves. In Quel'thalas they would bathe in the power of their Sunwell, and forget their legacy of desire and greed.\n\nThese distant descendants returned here, drawn by the hand of fate, doomed to repeat history. Hear their tale now, as I have...", completion = "We were proud and noble. Our faith in the light protected us, and with the Sunwell, we wanted for nothing.\n\nBecause of that blindness, we came here to repeat the tragedy of history, as our entire race would in time.", objectives = "Speak with the Quel'dorei Spirit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28535] = { id = 28535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Descendants of the High Elves", description = "Long after my death, my people would suffer an even greater mistake. The High Elves relied on the Sunwell and its glory. Never imagining a world without it, we would never make preparations to deal with such a fate.\n\nLater, when the Sunwell fell to the forces of the undead, what was left of my descendants would be lost and helpless... and the path they would take in response would change them forever.\n\nThe Sin'dorei, still striving for redemption, would return here as well...", completion = "We were not naive, as our forefathers were. We were suspicious and cunning and ready for betrayal at every turn.\n\nYet our pride and greed drove us to ruin once more. How many more will be lost to Kel'theril?", objectives = "Speak with the Sin'dorei Spirit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28536] = { id = 28536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Curse of Zin-Malor", description = "You have seen enough. Know that the Crystal of Zin-Malor brings only ruin to all around it.\n\nLeave this place, if you do not wish to join us.", completion = "The shade! Yes, I saw it too!", objectives = "Return to Kelek Skykeeper at Lake Kel'theril in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28537] = { id = 28537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Pursuit of Shades", description = "You say it spoke of a master? Of one who holds Zin-Malor?\n\nThis is grave news. You must act, {class}! I saw the shade fly off to the south. Take the path to the upper ruins, and you may be able to climb the frozen waterfall after it!\n\nAnd do not let your guard down... it may be waiting for you.", progress = "Did you find the shade? Was anything left to indicate its origin?", completion = "Let me see... faintly written, among the engraved incantations, is the name of its master!\n\n\"Umbranse...\"", objectives = "Pursue and slay the Shade of the Spiritspeaker and obtain any evidence of its master.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28538] = { id = 28538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cry of the Banshee", description = "So you are to be our savior? Very well then, I will bond myself with you. Through this bond I will be able to see through your eyes and communicate with you in the field.\n\nAccording to the plans you brought to us, the Stormpike have enlisted the aid of SI:7 at Sofera's Naze, to the north. SI:7 are comprised solely of humans - humans that we are able to use to our benefit.\n\nTake my mirror and travel north. Engage in combat with the SI:7 and bring them near death. Once they are injured, use the mirror.", completion = "<Melisara's voice pervades your thoughts.>\n\nThe humans will serve us in life and in death. I will be in contact with you shortly.", objectives = "Use the Banshee Mirror to capture 10 SI:7 Agents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28539] = { id = 28539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Stonetalon Mountains!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Huntress Jalin at Stardust Spire in Ashenvale.\n\nThe Horde's forces are poised to push into Stonetalon and they must be opposed! You can reach Stardust Spire by traveling to the southern part of Ashenvale Forest, near the border with Stonetalon.\n\nFor the glory and honor of the Alliance!", completion = "The Horde has bored a giant pass into the mountains, and we have few enough sentinels to spare. We have to find a way to stop them!", objectives = "Report to Huntress Jalin at Stardust Spire at the border between Ashenvale and the Stonetalon Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28540] = { id = 28540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doin' De E'ko Magic", description = "Mau'ari been makin' charms from da spirits of de wilds here for years now. Mau'ari just PLUCK de E'ko right outta de animals, and make charms for de kids, and de adventurers.\n\nOvah to de east, dere be a tall hill surrounded by de shardtooth bears. Up on de hill be Rimepelt, de oldest bear in de woods.\n\nMau'ari need dat bear for her magic. You bring me de bear's big ol' heart.", progress = "You got de bear? Let's see de bear.", completion = "Dis is nice, big heart! If you be interested, Mau'ari tell ya how I be gettin' de E'ko....", objectives = "Obtain Rimepelt's Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28541] = { id = 28541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cache of Mau'ari", description = "It be hard to describe de E'ko, but all creatures in dese lands have it... beasts, furbolg, even de frost giants. You got to open your mind and know where to look...\n\nWatch me now, an' I show you how to pull out de E'ko.", sourceObjective = "Watch Witch Doctor Mau'ari pull the E'ko from Rimepelt's body.", sourceObjectiveStatus = "unverified-source-field" }
quests[28542] = { id = 28542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Felwood!", description = "All able bodied members of the Horde are hereby ordered to report to Tenell Leafrunner at the Emerald Sanctuary in Felwood. The Cenarion Circle requires your help to wrest Felwood from the control of demons and other corrupt creatures!\n\nTo reach the Emerald Sanctuary, travel north from Ashenvale and follow the road until you reach the sanctuary.\n\nDestiny calls!", completion = "Welcome. My brothers and I are dedicated to the redemption and rejuvenation of this once-sacred forest.", objectives = "Report to Tenell Leafrunner at the Emerald Sanctuary in Felwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28543] = { id = 28543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Felwood!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Tenell Leafrunner at the Emerald Sanctuary.\n\nHis order requires your help to redeem Felwood from the demonic influences that rule the forest. Head north from Ashenvale and follow the road into Felwood until you reach the Emerald Sanctuary.\n\nFor the glory and honor of the Alliance!", completion = "There is much work to do here. The forest is on the mend, but without our help, it will take generations to restore this once-sacred wood.", objectives = "Report to Tenell Leafrunner at the Emerald Sanctuary in Felwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28544] = { id = 28544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Winterspring!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Donova Snowden at Frostfire Hotsprings.\n\nShe requires your help to overcome the threat of the Winterfall furbolg. To reach Winterspring, you must travel east from northern Felwood and traverse Timbermaw Hold.\n\nFor the glory and honor of the Alliance!", completion = "Thank goodness you're here. I've discovered the secret of the fierce Winterfall furbolg.", objectives = "Report to Donova Snowden at Frostfire Hot Springs in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28545] = { id = 28545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Winterspring!", description = "All able-bodied members of the Horde are hereby ordered to report to Donova Snowden at Frostfire Hot Springs. Her discoveries about the Winterfall furbolg may be the key to dealing with this threat once and for all.\n\nTo reach the Frostfire Hot Springs in Winterspring, you must travel east from northern Felwood and traverse Timbermaw Hold.\n\nDestiny calls!", completion = "Perhaps you can help me make sense of my discoveries about the source of the Winterfall Furbolgs' strength.", objectives = "Report to Donova Snowden at Frostfire Hot Springs in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28546] = { id = 28546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterfall E'ko", description = "In Winterspring, you will fight misguided creatures known as de Winterfall furbolg. These bear-people be so angry an' ferocious, dey live in a constant frenzy.\n\nBring me de E'ko of de Winterfall, an' I give you a frenzy so intense, ya legs will let you run like de wind!You will learn:", objectives = "Collect 5 Winterfall E'ko from any Winterfall furbolg in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28547] = { id = 28547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterfall E'ko", description = "In Winterspring, you will fight misguided creatures known as da Winterfall furbolg. Dese bear-people be so angry an' ferocious, dey live in a constant frenzy.\n\nBring me de E'ko of de Winterfall, an' I give you a frenzy so intense, ya legs will let you run like de wind!You will learn:", objectives = "Collect 3 Winterfall E'ko from any Winterfall furbolg in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28548] = { id = 28548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Desolace!", description = "All able bodied members of the Horde are hereby ordered to report to Furien at Tethris Aran in Desolace. The brave Horde warriors of Desolace need your help to beat back the armies of the Alliance and ancient demons.\n\nTo reach Tethris Aran, travel south from the Charred Vale in the Stonetalon Mountains.\n\nDestiny calls!", completion = "You... arrived just in... time...", objectives = "Report to Furien at Tethris Aran in Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28549] = { id = 28549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Southern Barrens!", description = "All able bodied members of the Horde are hereby ordered to report to Nura Pathfinder at the High Road in the Southern Barrens. With the recent Alliance victories in the Barrens, our enemies are threatening to cut our supply lines and leave our warriors stranded. We must act!\n\nTo reach the High Road, travel east from Stonetalon Mountains. If necessary, you can get a flight there from Doras in Orgrimmar.\n\nDestiny calls!", progress = "We must act quickly.", completion = "You've no doubt seen what the Alliance has done to the Barrens, {class}. If we don't act, there may not be a Horde presence here much longer.", objectives = "Report to Nura Pathfinder at the High Road in the Southern Barrens. Optionally, grab a flight there from Doras in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28550] = { id = 28550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Southern Barrens!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Commander Walpole at Stonetalon Pass in the Southern Barrens.\n\nOur brave soldiers have made tremendous gains in the Barrens, but they have paid a heavy price! Your efforts are needed to consolidate our gains. You can reach the Southern Barrens from the Stonetalon Mountains by traveling southeast through Greatwood Vale.\n\nFor the glory and honor of the Alliance!", completion = "We face heavy Horde counterattacks daily, {class}. We need every pair of hands we can get to keep them at bay.", objectives = "Report to Commander Walpole at Stonetalon Pass in northwestern Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28551] = { id = 28551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Southern Barrens!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Dockmaster Lewis near Northwatch Hold.\n\nOur brave soldiers have made tremendous gains in the Barrens, but they have paid a heavy price! Your efforts are needed to consolidate our gains. You can reach the docks outside Northwatch Hold by taking a boat from Booty Bay to Ratchet and traveling south along the coast.\n\nFor the glory and honor of the Alliance!", completion = "We're facing heavy resistance from the Horde, {class}. Any reinforcements are welcome.", objectives = "Report to Dockmaster Lewis at the docks outside Northwatch Hold in the Southern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28552] = { id = 28552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Dustwallow Marsh!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Calia Hastings at Theramore Isle.\n\nYou must aid SI:7's Calia Hastings in uncovering the threats to Theramore, both within the city and beyond its walls. You can reach Theramore Isle by taking the boat from Menethil or traveling across the marsh from the Southern Barrens.\n\nFor the glory and honor of the Alliance!", completion = "Deserters from the city guards are spreading discontent in the ranks. We have to get to the bottom of this before it undermines our defenses.", objectives = "Report to Calia Hastings at Theramore Isle in Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28553] = { id = 28553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Okrilla and the Blasted Lands", description = "I have one final dispatch to deliver to you, {name}.  It comes from Dreadmaul Hold, to the south, in the Blasted Lands.\n\nWarmatron Okrilla is waging battle against the Alliance forces of Nethergarde Keep, and she needs the assistance of a stout {class}.  You immediately sprung to mind.\n\nTravel south into the Blasted Lands, then head west.  Good luck, {name}.", completion = "Well, well, well... look what the Ruag dragged in!", objectives = "Report to Okrilla at Dreadmaul Hold in the Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28554] = { id = 28554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Dustwallow Marsh!", description = "All able bodied members of the Horde are hereby ordered to report to Krog at Brackenwall Village. The marsh is overrun with enemies of many kinds and the Alliance forces there are dangerously strong.\n\nYou can travel to Dustwallow Marsh by following the path from the eastern part of the Southern Barrens toward Brackenwall Village. Or, you can get a flight there from Doras in Orgrimmar.\n\nDestiny calls!", progress = "Aka'Magosh, {class}.", completion = "If we can get things straightened out here, we have a chance to strike at the Alliance while most of their forces are busy in the Barrens.", objectives = "Report to Krog at Brackenwall Village in Dustwallow Marsh. Optionally, grab a flight there from Doras in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28555] = { id = 28555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expel the Envoys", description = "<Not yet implemented.>" }
quests[28556] = { id = 28556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Hand", description = "We must break the fingers of the Stormpike if we are to stop their incursion.\n\n<Cromush hands you a small package.>\n\nWithin this package are four high-yield goblin explosives. You are to infiltrate each of the four fingers - Sofera's Naze, Corrahn's Dagger, the Headland and Gavin's Naze - and plant a goblin pocket-nuke at each.\n\nOnce you have done that - as well as all that Melisara asks of you - return to me.", progress = "Have you planted the pocket-nukes?", completion = "Once Melisara is through with you we will detonate the explosives!", objectives = "Plant a Goblin Pocket-Nuke at Sofera's Naze, Corrahn's Dagger, the Headland and Gavin's Naze.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28557] = { id = 28557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Uldum!", description = "All able-bodied members of the Horde are hereby ordered to report to Adarrah at the Thistleshrub Valley in Tanaris.\n\nAncient texts tell us that Uldum is home to untold riches and treasures beyond compare. Go forth and claim these in the name of the Horde!\n\nYou can reach Adarrah's caravan by traveling to the southwestern part of Tanaris and looking for her in Thistleshrub Valley.\n\nDestiny calls!", completion = "You could be one of the very first mortals to set foot in Uldum in millenia. Just think of the treasures that await us!", objectives = "Speak with Adarrah in Thistleshrub Valley in western Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28558] = { id = 28558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Uldum!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Adarrah at Thistleshrub Valley in Tanaris.\n\nBe one of the first to enter glorious Uldum and claim its treasures in honor of the Alliance!\n\nYou can reach Adarrah's caravan by traveling to the western reaches of Tanaris.\n\nFor the glory and honor of the Alliance!", completion = "There are wonders just waiting to be discovered beyond this valley. And they will be ours!", objectives = "Speak with Adarrah at Thistleshrub Valley in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28559] = { id = 28559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Bloodmyst Isle!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Vorkhan the Elekk Herder at Kessel's Crossing.\n\nThe people of Bloodmyst need your help to deal with treacherous blood elves and dangerous creatures loose on the island. You can reach Kessel's Crossing on Bloodmyst Isle by taking the bridge north from Azuremyst Isle.\n\nFor the glory and honor of the Alliance!", completion = "So you're here to help? Well, there's plenty to do...", objectives = "Report to Vorkhan the Elekk Herder at Kessel's Crossing on Bloodmyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28560] = { id = 28560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Ghostlands!", description = "All able bodied members of the Horde are hereby ordered to report to Arcanist Vandril at Tranquillien in the Ghostlands.\n\nYour help is needed to turn back the numberless Scourge invaders and secure the help of the Forsaken in fighting our common enemy.\n\nTo reach Tranquillien, follow the road south from Fairbreeze Square and into the Ghostlands.\n\nDestiny calls!", completion = "Your arrival here is fortuitous, {class}. We cannot fight the Scourge without help.", objectives = "Report to Arcanist Vandril at Tranquillien in the Ghostlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28561] = { id = 28561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nahom Must Hold", description = "As soon as we make our move west in order to attack Neferset City, the enemy will strike us from the east, where we'll be weak.\n\nNahom will be the first to fall, and if it does, Ramkahen will soon follow.\n\nA small detachment is there already.\n\nGet a briefing from them.  I want you to make sure that they hold Nahom until I can send more troops there.", completion = "{name}!  It's you!  My regiment was ambushed on our way here.\n\nOur captain was slain, leaving me in command... until you got here, that is... sir!", objectives = "Report to the regiment at Nahom in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28562] = { id = 28562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Westfall!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Lieutenant Horatio Laine at the Jansen Stead.\n\nWestfall has been overrun by beggars and transients, leading to a massive increase in criminal activity. Your help is needed to restore order to the populace. You can reach the Jansen Stead in Westfall by traveling west from Elwynn Forest.\n\nFor the glory and honor of the Alliance!", completion = "Murder, rookie. That's what you're looking at on the ground in front of us.", objectives = "Report to Lieutenant Horatio Laine at the Jansen Stead in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28563] = { id = 28563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Redridge Mountains!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report Watch Captain Parker at Tower Watch in the Redridge Mountains.\n\nCaptain Parker's forces have come under attack from marauding gnolls and orcs. The people of Lakewood are in peril and your aid is needed to safeguard them. Travel east from the border of Elwynn Forest and into the Three Corners area of Redridge to reach Tower Watch.\n\nFor the glory and honor of the Alliance!", completion = "Heard Westfall was in some deep doody.\n\n<Parker doesn't even turn to face you.>\n\nWell, we got our own set of problems here. See them gnolls out there? Looks like they're actin' up again. I don't like it. Don't like it one bit.", objectives = "Report to Watch Captain Parker at Tower Watch in Redridge Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28564] = { id = 28564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Duskwood!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Commander Althea Ebonlocke in Darkshire.\n\nThe commander's watchmen are stretched thin defending against marauding wolves and bands of wild worgen. They cannot hold out for long without your help. You can reach Darkshire in Duskwood by following the road south at the border between Elwynn Forest and the Redridge Mountains.\n\nFor the glory and honor of the Alliance!", completion = "You are the help that we requested?\n\n<Althea sighs.>\n\nI suppose you will have to do.", objectives = "Report to Commander Althea Ebonlocke at Darkshire in Duskwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28565] = { id = 28565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Wetlands!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Mountaineer Rharen at Dun Algaz.\n\nIn the wake of the cataclysm's destruction, Wetlands has become overrun with wild beasts, orcish raiders, and savage gnolls! To reach the Wetlands, you must travel north from Loch Modan through the dwarven hold of Dun Algaz.\n\nFor the glory and honor of the Alliance!", completion = "We haven't gotten much in the way of reinforcements lately. We can use every pair of hands we can get.", objectives = "Report to Mountaineer Rharen at Dun Algaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28566] = { id = 28566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decimation", description = "<Melisara's image appears before you.>\n\nThe Stormpike forward camp sits atop Corrahn's Dagger, west of Sofera's Naze. You must enter the camp and slaughter every dwarf that you see. They must be taught what it means to fear and there is no finer lesson than absolute decimation.\n\nNo survivors, {name}. Even their captain - especially their captain - must die.\n\nI will be in contact.", completion = "<Melisara's voice pervades your thoughts.>\n\nThey will see the bloodshed and they will hesitate. Hesitation will make them think twice about ever attacking us again.", objectives = "Kill Captain Iceheart and 12 Stormpike Soldiers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28567] = { id = 28567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Loch Modan!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Pilot Hammerfoot at South Gate Outpost.\n\nThe destruction of the Stonewrought Dam and the resurgence of the kobolds and troggs has the mountaineers stretched thin. Reinforcements are desperately needed! Travel east through South Gate Pass from eastern Dun Morogh to reach South Gate Outpost.\n\nFor the glory and honor of the Alliance!", completion = "Have our leaders finally heard my pleas? We're down to just a handful of pilots and mountaineers to defend Loch Modan.", objectives = "Report to Pilot Hammerfoot at South Gate Outpost in Loch Modan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28568] = { id = 28568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Silverpine Forest!", description = "All able-bodied members of the Horde are hereby ordered to report to Grand Executor Mortuus at Forsaken High Command in Silverpine Forest.\n\nNow, more than ever, your help is needed in routing the enemy infestation of the region and conquering the port of Gilneas!\n\nTo reach Forsaken High Command you must travel south through Tirisfal Glades and enter Silverpine Forest. From there, follow the road south until you reach Forsaken High Command.\n\n Destiny calls!", completion = "Most excellent! A new recruit has arrived. There is much to do... much to do I say.", objectives = "Report to Grand Executor Mortuus at Forsaken High Command in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28569] = { id = 28569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bogpaddle Bullet", description = "I've heard stories about a road to the Swamp of Sorrows.  Mysterious tales of a meandering mountain pathway that completely bypasses Redridge and poops you right out into Bogpaddle!\n\nIf you run out of things to do, I suppose you'll have to leave.  And we'll all be sad.  When you do leave, talk to Sharon Boomgetter in the southeastern corner of the Steppes.  She'll give you a ride.\n\n<Oralius tilts his head, as if listening to something.>\n\nWinky?  WINKY!  NO!", completion = "Time is money, {class}... and I've got plenty of each.\n\nWhat can I do for you?", objectives = "Speak with Sharon Boomgetter in the southeastern corner of Burning Steppes to ride the Bogpaddle Bullet to the Swamp of Sorrows. Then speak with Trade Baron Silversnap in Bogpaddle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28570] = { id = 28570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bogpaddle Bullet", description = "You're quite the {race}, aren't you?  Look at you... you're all grown up already.  And we only just met!\n\nI know how it'll go... soon you'll run out of things to do here at Flame Crest.  You'll promise to come back.  But you never will.\n\nKibler's seen it all before.\n\nWhen you do leave, talk to Sharon Boomgetter in the southeastern corner of the Steppes.  She'll give you a ride on the bullet.\n\nWhat?  Oh, it's just a rocket.  Perfectly safe.", completion = "Time is money, {class}... and I've got plenty of each.\n\nWhat can I do for you?", objectives = "Speak with Sharon Boomgetter in the southeastern corner of Burning Steppes to ride the Bogpaddle Bullet to the Swamp of Sorrows. Then speak with Trade Baron Silversnap in Bogpaddle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28571] = { id = 28571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Hillsbrad Foothills!", description = "All able bodied members of the Horde are hereby ordered to report to High Executor Darthalia at Southpoint Gate in Hillsbrad Foothills. The Forsaken war machine marches ever onward, securing Lordaeron for the Horde!\n\nTo reach Southpoint Gate you must follow the road south through Silverpine Forest and take the east fork leading into Hillsbrad Foothills.\n\nOnward, <brother/sister>! Destiny calls!", completion = "I was wondering when reinforcements would show up. Suit up, {name}. It's time to dispense some justice!", objectives = "Report to High Executor Darthalia at Southpoint Gate in Hillsbrad Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28572] = { id = 28572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Arathi Highlands!", description = "All able bodied members of the Horde are hereby ordered to report to Dark Ranger Alina at Galen's Fall. The Dark Lady's forces need your help to expand the dominions of the Horde and drive back the Alliance interlopers.\n\nTo reach the Arathi Highlands, travel east from Hillsbrad Foothills and follow the road past Thoradin's Wall.\n\nDestiny calls!", completion = "At last, the Warchief's reinforcements have arrived. The Dark Lady has plans for you, as she does for us.", objectives = "Report to Dark Ranger Alina at Galen's Fall in Arathi Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28573] = { id = 28573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Arathi Highlands!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Captain Nials at Refuge Pointe.\n\nAncient Stromgarde's honor must be redeemed! Too long have ogres and criminals sullied its streets. Travel north from the Wetlands and cross the Thandol Span to reach Arathi. Follow the road to Refuge Pointe and present yourself to the captain.\n\nFor the glory and honor of the Alliance!", completion = "Would that you were a company, but we'll have to make do with with what we have.", objectives = "Report to Captain Nials at Refuge Pointe in Arathi Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28574] = { id = 28574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: The Hinterlands!", description = "All able bodied members of the Horde are hereby ordered to report to Elder Torntusk at Revantusk Village.\n\nNow that the Wildhammer dwarves have officially thrown in their lot with the Alliance, they have made themselves our enemies. They must be defeated!\n\nTo reach Revanktusk Village, cross into the Hinterlands from the mountain pass in eastern Hillsbrad Foothills and make your way to the eastern coast.\n\nDestiny calls!", completion = "Have you come to help us against the Wildhammers? The Warchief knows that what happens here will be important to the Horde's future.", objectives = "Report to Elder Torntusk at Revantusk Village in the Hinterlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28575] = { id = 28575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Western Plaguelands!", description = "All able bodied members of the Horde are hereby ordered to report to Koltira Deathweaver at Andorhal.\n\nThe Alliance forces are advancing into the ruined city of Andorhal, seeking to claim it for themselves. We must counter them before they can gain a foothold there!\n\nCross the Bulwark at the eastern end of Tirisfal Glades and follow the roads southeast to Andorhal and meet up with our forces there.\n\nDestiny calls!", completion = "Is this all the warchief can spare? Don't worry, you'll be put to good use.", objectives = "Report to Koltira Deathweaver at Andorhal in the Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28576] = { id = 28576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Western Plaguelands!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Thassarian at Andorhal.\n\nOn the heels of our early victories in Andorhal, the Forsaken have decided to launch a counterattack. Your help is needed to beat back the Scourge and Horde and reclaim lost Andorhal.\n\nTo reach Andorhal, travel north through the Hillsbrad Foothills and follow the road beyond Chillwind Camp.\n\nFor the glory and honor of the Alliance!", completion = "There is much to be done here. Both of our enemies are relentless and would slaughter us without mercy the moment we sheathe our blades.", objectives = "Report to Thassarian at Andorhal in the Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28577] = { id = 28577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Eastern Plaguelands!", description = "All able bodied members of the Horde are hereby ordered to report to Fiona on the east bank of the Thondroril River.\n\nThe Argent Crusade has reinforced its presence in the Plaguelands and it needs your help to consolidate its victories.\n\nCross the Thondroril River at the eastern border of the Western Plaguelands and look for Fiona on the far bank.\n\nDestiny calls!", completion = "Perhaps you can help, {class}.", objectives = "Report to Fiona on the east bank of the Thondroril River in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28578] = { id = 28578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Eastern Plaguelands!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Fiona on the east bank of the Thondroril River.\n\nThe Argent Crusade needs your help to win back the Eastern Plaguelands from the grasp of the Scourge.\n\nTo reach the Eastern Plaguelands, cross the Thondroril River from the Western Plaguelands and look for Fiona on the eastern bank.\n\nFor the glory and honor of the Alliance!", completion = "Perhaps you can help, {class}.", objectives = "Report to Fiona on the eastern bank of the Thondroril River in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28579] = { id = 28579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Badlands!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Gek Nozzlerocket at Light's Hope Chapel in the Eastern Plaguelands.\n\nYour help is needed to survey the damage done by Deathwing, and the disposition of Horde forces in the Badlands.\n\nGek has agreed to provide transportation to the Badlands via rocket, in exchange for your help. Look for him at Light's Hope Chapel in the Eastern Plaguelands.\n\nFor the glory and honor of the Alliance!", completion = "You must be here to help Fuselight! Let's get you to the Badlands right away.", objectives = "Report to Gek Nozzlerocket at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28580] = { id = 28580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Badlands!", description = "All able bodied members of the Horde are hereby ordered to report to Gek Nozzlerocket at Light's Hope Chapel in the Eastern Plaguelands.\n\nThe Alliance is desperate to gain a foothold in the Badlands. Your duty will be to keep them at bay and learn about the destruction wrought by Deathwing.\n\nGek has agreed to provide transportation to the Badlands by rocket. Meet with him at Light's Hope Chapel.\n\nDestiny calls!", completion = "Sure, I can get you to the Badlands, but when you get there, I want you to agree to help my comrades.", objectives = "Report to Gek Nozzlerocket at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28581] = { id = 28581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Searing Gorge!", description = "All able bodied members of the Horde are hereby ordered to report to Jack Rockleg at Thorium Advance.\n\nThe Shattered Hand reports that the Dark Iron dwarves of the Searing Gorge seem to be preparing for something. Your duty is to learn all you can about their scheming and put a halt to it.\n\nYou can reach the Searing Gorge by following the road west from the Badlands.\n\nDestiny calls!", completion = "We, too, are suspicious of the Dark Irons' recent activities.", objectives = "Report to Jack Rockleg at Thorium Advance in the Searing Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28582] = { id = 28582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Searing Gorge!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Jack Rockleg at Thorium Advance.\n\nSI:7 reports that the Dark Iron dwarves of the Searing Gorge seem to be preparing to attack. Your duty is to learn all you can about their scheming and put a halt to it.\n\nYou can reach the Searing Gorge by following the road west from the Badlands.\n\nFor the glory and honor of the Alliance!", completion = "We, too, are suspicious of the Dark Irons.", objectives = "Report to Jack Rockleg at Thorium Advance in the Searing Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28583] = { id = 28583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krazzworks", description = "This new shredder design is tops, {name}. Tops! Next step is to protect my intellectual property. There are patents to file, traders to mark, ceases to desist. Oh, and the bribes!\n\nHere, take this patent application to Captain Krazz at the Krazzworks. He survived the destruction of his zeppelin, so he's probably hungry for new business opportunities.\n\nThe Krazzworks is due north of here, atop a perfectly safe mountain peak. Go ahead, kid. Chop chop!", progress = "I know you! You were on the Zeppelin with me on the way in.", completion = "What's this? The \"{name}-o-matic:\" a shredder with an integrated missile platform?\n\nBah! Already patented by Labor Captain Grabbit in Azshara. Worthless!\n\nWhat I really need is a machine that knocks dwarves from the sky.", objectives = "Take the Patent Application to Captain Krazz at the Krazzworks in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28584] = { id = 28584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quality Construction", description = "Look here, chief, if it weren't for this bumbly idiot across from me, the Krazzworks would be holding up just fine.\n\nUnfortunately for everyone involved, \"Fancypants\" Rothman here decided to deploy the place on top of a mountain! I mean really, who does that?\n\nSo, we got leaks all over the place due to faulty valves. Think you could take this blast tape and seal 'em up for me?", progress = "Look, I'm just a simple cartographer, but according to my estimates, not to mention what my eyes are telling me, there are a few more faulty valves that need to be sealed.", completion = "There you go. Now hows about we use this blast tape on Rothman's mouth?", objectives = "Use the Blast Tape to seal 10 Faulty Valves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28585] = { id = 28585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Polished" }
quests[28586] = { id = 28586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pool Pony Rescue", description = "This jerk across from me is getting all of our people killed!\n\nBrett \"the Bummer\" unpacked the Krazzworks in the wrong place and now it's highly unstable. The explosions from the instability are throwing our laborers off of the platforms and into the water below.\n\nYou don't mind flying down there and rescuing them with some pool ponies, {name}?", progress = "Maybe you'd be willing to fly back down there and rescue a few more of our laborers?", completion = "Thanks, {name}! Now if we could just get the Krazzworks stable so that our people would stop being thrown off of the platforms.", objectives = "Use the Pool Ponies to rescue 10 Krazzworks Laborers that have fallen into the water.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28587] = { id = 28587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid of the Frostwolf", description = "I will study the Stormpike battle plans and prepare for an assault. I need you to go to Alterac Valley and enlist the aid of the Frostwolf Clan: the very clan of our former warchief, Thrall. They will help us battle the Stormpike dwarves! Together, we will crush the invaders and see them driven out of Lordaeron for good!\n\nGo now, {name}. Alterac Valley is northeast of Tarren Mill. Find Voggah Deathgrip and tell him that the Horde requires the aid of the Frostwolf!\n\nLOK'TAR!", completion = "You come from Tarren Mill? You reek of death...", objectives = "Speak to Voggah Deathgrip at Alterac Mountains in Hillsbrad Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28588] = { id = 28588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildhammer Infestation", description = "While these two idiots argue about who royally messed up here, we've got a full-scale invasion of the Krazzworks taking place!\n\nThose no-good Wildhammer are all over the place. Get out there and clear the Krazzworks of those smelly ale-guzzling pests.", completion = "You got the chops for killing dwarves, that's for sure, {name}. This is a good thing.\n\nNext up, more dwarf slayage!", objectives = "Slay 10 Wildhammer Raiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28589] = { id = 28589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything But the Kitchen Sink", description = "You gotta do something about them Wildhammer Stormtalons. They're tearing us up!\n\nProblem is, we're out of ammo, so we had to improvise. We loaded up my Krazz Cannons with all kinds of stuff: pool ponies, Kaja'Cola cans, food containers, fuelcells, tires... you get the picture.\n\nBasically, everything but the kitchen sink.\n\nThink you're in the mood for some target practice?", completion = "That's the spirit! Must be pretty humiliating being shot down by junk.", objectives = "Slay 15 Wildhammer Stormtalons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28590] = { id = 28590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reprisal", description = "I happen to know some Alliance scum that have somethin' coming to them. And they have something that belongs to us. I've authorized an all out assault on Highbank.\n\nBoard the Skyshredder and join the assault. Patch will fill you in on the details as you arrive.", completion = "Good to have you, {name}. Ready to sew some chaos?", objectives = "Speak to Patch aboard the Skyshredder circling Highbank.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28591] = { id = 28591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off The Wall", description = "You look like a <man/girl> who likes some action. Get on one of those turrets and lay waste to their defenses on the wall.\n\nBe quick about it, will you? Before we go up in a big ball of fire preferably.", completion = "Marvels of modernized goblin destructivity, eh? I love these babies.", objectives = "Kill 80 Highbank Marksman, 12 Highbank Cannoneers, and 4 Highbank Cannons with a Skyshredder Turret.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28592] = { id = 28592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parting Packages", description = "I'm sure Patch has some grand scheme in mind, but this wouldn't be an assault if we didn't leave some explosive presents behind.\n\nGet down there and plant some of these explosives on the boat, in the keep entrance, and in one of those northern towers. That should be enough to leave them reeling.\n\nWe're heading down to the ground as well. Meet us at the eastern tower when you're through.", progress = "Did you share the love?", completion = "Hahah! Wonderful show.\n\nThat should be a proper welcome to the highlands.", objectives = "Set bombs on the boat, in the keep entrance, and in one of the northern towers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28593] = { id = 28593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Utmost Importance", description = "When Garrosh's zeppelin went down, so did the induction samophlange that you recovered for us in Azshara. The Alliance have it somewhere in that keep, and Krazz wants it back.\n\nThe basement of the keep would be my best guess, so start there. When you get your hands on it, bring it back to me near the eastern tower.", progress = "Krazz is waitin'. Keep it moving.", completion = "Brilliant! Krazz will love you something mighty for bringing this one home. Good on you.", objectives = "Recover the Induction Samophlange.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28594] = { id = 28594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Highbank, Crybank", description = "Get down there and make a mess of those Alliance rabble. Any of'm will do. I just want'm scattered while you're in there after the real target.\n\nFind us near the eastern tower when you're done.", completion = "And that's how it's done. Scattered to the wind. Not quite the fighting force they boast themselves to be, eh?", objectives = "Kill 10 Highbank defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28595] = { id = 28595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krazz Works!", description = "That's it. We're all wrapped up. Let's ship out.\n\nNewt's got some gyrocopters tethered at the top of the tower. Go meet up with her for a quick trip back to Krazzworks. We'll mop up here.", progress = "Tell me you came through? You always come through. Show me my beauty!", completion = "Now that's what I wanted to see! I'll have this fleet back up in no time with this beauty.\n\nYou know just how I like it, {name}. I know just how you like it too - take this.", objectives = "Speak to Newt to secure a ride back to Krazzworks, then give the Induction Samophlange to Captain Krazz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28596] = { id = 28596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Highbank!", description = "Welcome to the highlands, soldier. You're here just in time.\n\nHorde troops just launched an assault from the air. Step up and do something about it. Clear them out!", progress = "You'll have to kill a few more than that, soldier.", completion = "That's more like it. We should be able to mop this up from here.", objectives = "Kill 10 Horde attackers within Highbank.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28597] = { id = 28597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burnin' at Both Ends", description = "Har! We get to jump right inta the action, {name}. Looks like Highbank has whatcha call a zeppelin problem: that airship is poundin' the crap outta the walls.\n\nListen, I've got me an idear so stupid it's genius. I just need some cannon powder.\n\nCollect as much as you can find around Highbank an' meet me by the trade area!", progress = "I need more powder! Get me more powder! More more more!", completion = "Aye, that'll do 'er.\n\n<Flintlocke stuffs some of the powder in his mouth.>\n\nOhhh, fresh. Heady. Redridge fine grain with a hint of Westfall sulphur and a mild aftertaste. Highbank gets the good stuff.", objectives = "Collect 10 bags full of Cannon Powder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28598] = { id = 28598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiming High", description = "Lookie here, {name}. I found the biggest gun in Highbank! We're gonna try a technique handed down ta me by my pappy, from his pappy, from his pappy, shortly before he got blowed up.\n\nIt's called the \"{class}-shot.\"\n\nYou take a {race} {class}, and load <him/her> inta a gigantic cannon, and then ya - oh relax. This usually works.\n\nTake these explosives, then wait here next ta me. As soon as that blimpy comes around I'll blast you onto tha deck. Plant the explosives in 'er belly and, oh I dunno, make it up as you go.", progress = "Ain't no problem a bomb can't solve.", completion = "<Flintlocke wipes tears from his eyes.>\n\nOh, {name}. {name}!\n\nThat ... were beautiful.", objectives = "Wait for Fargo Flintlocke to get you onto the zeppelin and then set his explosives in its lower chamber.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28599] = { id = 28599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurdran's Waitin'", description = "It looks like the attack stopped, {name}. Which is a shame, 'cuz we never got to use the {class}-rocket.\n\nAnyways, Kurdran Wildhammer is up in the top of the keep an' I'm sure he'll be wantin' to gives ya a hero's welcome. Yeh earned it! Go talk to 'im!\n\nI'll move on ahead and scout out the beach.", completion = "The King himself sent you? Good to hear that Stormwind is secure.\n\nI was expecting more in the way of troops, but word is that the Alliance fleet was ambushed by the Horde on the way here. They gave as good as they got, but the fleet is in shambles.\n\nIf we're to make any forward progress here in the Highlands, we're going to need the help of heroes like you.", objectives = "Speak to Kurdran Wildhammer inside of the Highbank Keep in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28600] = { id = 28600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Matters of Loyalty", description = "I have no authority over such matters. You must speak to our leader, Drek'Thar. I have already sent word of your arrival to Frostwolf Keep. Drek'Thar will be out to speak with you personally.", completion = "<High Warlord Cromush's face turns white.>\n\nTHEY HAVE FORSAKEN US? THEY HAVE FORSAKEN THE HORDE? This cannot be!\n\nI...\n\n<Cromush falls to one knee.>\n\nI... I WILL BE FINE. We will do this without their aid. To hell with the Frostwolf!", objectives = "Speak to Drek'Thar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28602] = { id = 28602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Be Prepared", description = "Every adventurer worth their salt knows never to step foot in a cave, dungeon, crypt or tomb without an ample supply of rope... right?\n\nWell, mine was in that wagon full of explosives that you set off.\n\nHow about searching around here and seeing if you can't find some.", progress = "How goes the search?", completion = "Something tells me I'm going to need this.", objectives = "Collect 6 Rope Pieces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28603] = { id = 28603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltration", description = "For your next mission I want you to travel west to the Headland and infiltrate the Stormpike training grounds. Though there are hundreds of Stormpike trainees there, one of my banshees will disguise you to look like one of the humans captured earlier, allowing you to walk freely among the enemy.\n\nEnter the Headland and find the Stormpike instructors. Once found, coerce them into attacking you! When they attack, kill them. With their instructors dead, they will be unable to train more soldiers!", completion = "<Melisara's voice pervades your thoughts.>\n\nPerfectly handled. You could easily be a Deathstalker. And what could they have even done to you? You acted in self defense!\n\nNow to deal with the final finger.", objectives = "Kill Instructor Rufus, Drill Sergeant Magnus and Captain Crudbeard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28604] = { id = 28604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deception and Trickery", description = "As long as I am by your side the enemy will think of you as one of their own. Your newfound humanity, however, will not allow you to be reckless. If you draw attention to yourself the dwarves will grow suspicious and likely attack!\n\nWith that said, I have a plan. Take this barrel of poisoned water and use it to sate the thirst of the tired Stormpike trainees. Once they drink from it they will become deathly ill, eventually succumbing to the poison.", progress = "Deception and trickery - these are your tools!", completion = "They won't die immediately, but they WILL die! When they finally piece together who was responsible for the deaths of their soldiers, you will be long gone - a phantom of death!", objectives = "Use the Barrel of Water to Poison 30 Stormpike Trainees.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28605] = { id = 28605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Domination", description = "<Melisara's thoughts intermingle with your thoughts.>\n\nThe last task will be an assault against the siege technicians of Gavin's Naze, located west of the Headland. Venture to the final finger and lay waste to the dwarf and gnome engineers that build and fortify the Stormpike machines of war. Be sure to plant Cromush's final pocket-nuke as well.", progress = "Is it done?", completion = "With the Stormpike forces maimed, the time has come for detonation!", objectives = "Kill 10 Stormpike Engineers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28606] = { id = 28606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Keys to the Hot Rod" }
quests[28607] = { id = 28607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Keys to the Hot Rod", objectives = "You lost your Keys to the Hot Rod somewhere?\n\nNo problem, boss. I always like to keep a spare set handy just in case.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28608] = { id = 28608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow Grave", description = "I'm pleased to see that you're up and walking around, {name}.  You've held up nicely, especially after being dead for so long!\n\nOthers weren't as lucky.  If you wouldn't mind, I need you to fetch my embalming fluid and some twine to stitch up these bodies.  You'll find both in the Shadow Grave, the building just behind me.\n\nHere, Darnell will join you.  He knows the way.", progress = "You will find the items within the Shadow Grave.  I believe I left them on my work table.", completion = "Exactly what I needed.  You'll be an asset to the Forsaken, {name}.\n\nYou know, word has it that you were quite the {class} in your previous life.  Perhaps I should assign you to a more exciting task.", objectives = "Obtain the Thick Embalming Fluid and the Corpse-Stitching Twine from the Shadow Grave in Deathknell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28609] = { id = 28609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammer Time", description = "The three of us have been arguing for weeks over whose weapons are superior.\n\nI won't let anyone tell me my maces are second best. Kilram's axes and Seril's swords could never match the pure strength of my craft.\n\nI'm tired of arguing. It's time to show those two I'm right with a demonstration. If you would, dear, head outside and tell Deez Rocksnitch that I need the biggest boulder he can find!", completion = "Lilith wants a boulder moved inside the observatory, eh? That's my business: consolidated materials. I usually don't get individual buyers, but hey, I won't ask questions.", objectives = "Speak with Deez Rocksnitch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28610] = { id = 28610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rubble Trouble", description = "If you want to get a boulder in there, you can use my own patented Boulder-in-a-Box! Normally I'd just sell you one up front, but I'm fresh out of materials.\n\nEarth elementals have been popping up on the peak directly south of town. They're a good source of rubble. If you bring me back a good amount, I'll pay you for the restock, and I'll throw in a Boulder-in-a-Box absolutely free!", progress = "You got that rubble?", completion = "Looks like a good amount! Here's your pay, as promised...", objectives = "Collect 6 Prime Rubble Chunks from Frostshard Rumblers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28611] = { id = 28611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defilers' Ritual", description = "Ah, I can already see more clearly, {name}.\n\nWe are right to be wary of the evil Neferset.  I can already sense that they're behind the forces that corrupt the river.\n\nGo underwater once more and find the Murkdeep Cavern.  You will find the Neferset are performing a foul ritual of corruption.\n\nStop them so the river is cleansed once again.", progress = "Is it done, {name}?", completion = "The waters of the river are nearly cleansed.  Our prophetic visions will soon return.", objectives = "Stop the Neferset Ritual at the Murkdeep Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28612] = { id = 28612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harrison Jones and the Temple of Uldum", description = "After all we've been through, it looks like everything's actually coming together!\n\nWe're just steps away from the coffer... I've researched the codes to reveal it... Schnottz thinks we're dead....\n\nYou know, we might just pull this off after all!", completion = "Lucky fer you, this ol' dwarf's still got a few tricks up his sleeve!\n\nHeehee! ...shoulda seen tha look on yer faces!", objectives = "Recover the Coffer of Promise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28613] = { id = 28613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See You on the Other Side!", description = "Alright, {name}. We've bought ourselves a little breathing room, but there's no time to lose.\n\nFollow me!", completion = "So far, so good...", objectives = "Speak to Harrison Jones at the top of Maker's Ascent in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28614] = { id = 28614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bearzerker", description = "High Chieftain Winterfall's absence has done little to quell the rage of the Winterfall. In his absence, their greatest warrior has rose to a position of terrible power.\n\nGrolnar the Berserk lurks in the cave at the top of Winterfall Village, gorged on enough corrupt firewater to kill ten lesser furbolgs.\n\nHe has become a bloated and horrible beast! Our warriors have been unable to face him... do you have the strength to defeat him, {class}?", progress = "Has Grolnar fallen?", completion = "Your actions prove yourself a mighty warrior to me and all the Timbermaw!\n\nLet us hope the Winterfall will be defeated for good now...", objectives = "Slay Grolnar the Berserk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28615] = { id = 28615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning the Earth", description = "Despite their corruption and madness, the Winterfall barely cling to their shamanic powers. It disturbs me to see the power of the elements used by them to harm my tribe and other innocents.\n\nWe will turn their totems against them! Take my own totem with you into Winterfall Village. Use its powers on the Winterfall's totems from afar, and the fury of the earth will be unleashed on all nearby!\n\nNeedless to say... keep a safe distance!", completion = "May the Winterfall never threaten the Timbermaw again. Thank you, {name}.", objectives = "Use Tanrir's Overcharged Totem to overload 4 Winterfall Earth Totems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28616] = { id = 28616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormpike Apocalypse", description = "Before we continue, let us have a moment of silence for our fallen brother, Orkus, for without him, we would have been destroyed by the Stormpike onslaught. This is for you, brother!\n\n<Cromush takes a knee.>\n\nNow, {name}, do not think that I forgot your part in all of this! That is why you get the honors of detonating the goblin pocket-nukes.\n\nAre you ready? FOR THE HORDE!", completion = "With the fingers destroyed and the hand shattered, the Stormpike will have no choice but to scurry back to their cave in Alterac Valley.\n\n<Cromush spits.>\n\nWarchief Hellscream will hear about your bravery, {name}.\n\nAnd rest assured that he will know of the Frostwolf clan's treason!", objectives = "Witness the Stormpike Apocalypse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28617] = { id = 28617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flower Power", description = "You know how to use the spitters, but did you know that if you use a sunflower you can grow things faster? We'll grow some sunflowers and then we'll plant some spitters to push back Warden Stillwater's crazed monstrosities.\n\nLet's go!", completion = "I think that was just the start of it, bud! MORE INCOMING!", objectives = "Survive a Massive Wave of Zombies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28618] = { id = 28618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boulder Delivery", description = "Here you go, as promised! One Boulder-in-a-Box.\n\nLilith was asking for this, wasn't she? She's my only customer!", progress = "Oh, it's you again. Where's that boulder?", completion = "Ah, you actually brought the boulder! I'm a bit surprised.\n\nStand back and witness the pinnacle of craftsmanship.", objectives = "Deliver the Boulder-in-a-Box to Lilith the Lithe in Everlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28619] = { id = 28619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Arathi Highlands!", description = "All able bodied members of the Horde are hereby ordered to report to Dark Ranger Alina at Galen's Fall. The Dark Lady's forces need your help to expand the dominions of the Horde and drive back the Alliance interlopers.\n\nTo reach the Arathi Highlands, travel east from Hillsbrad Foothills and follow the road past Thoradin's Wall.\n\nDestiny calls!", completion = "At last, the Warchief's reinforcements have arrived. The Dark Lady has plans for you, as she does for us.", objectives = "Report to Dark Ranger Alina at Galen's Fall in Arathi Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28620] = { id = 28620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eastpoint Tower", description = "Our outpost in the southeast is having some problems. I don't have any details other than... well, let me just read from the latest letter:\n\n\"The orcs have grown petulant. Send help or I will have them beaten with reeds.\"\n\nThat's it. It was sent from our chief psylosopher, Nils Beerot. Yea, I have no idea what that means either. Could you please head to Eastpoint Tower and find out what he needs? I can't take any more of these cryptic letters!\n\nJust head south and then follow the road east.", completion = "That imbecile finally sent help, did he? These two orcs are a lost cause. They are stricken with something that I have termed \"Durnholde Syndrome.\" They were both locked up for so long that they grew an affinity for their captors. Now they sit upon my couch with their big, iron balls and cry.\n\nHopefully you will prove to be more useful.", objectives = "Speak to Nils Beerot at Eastpoint Tower in Hillsbrad Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28621] = { id = 28621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put That Baby in the Cradle!", description = "Och!\n\nYou an' junior took yer sweet time gettin'  'ere, din't ya!?\n\n<Drinkin' ale/Holdin' hands>, takin' in the sights, I'll wager.\n\nDon't go breakin' yer arm pattin' yerself on the back now, the real work's just beginnin'!\n\nThere be more ta this ancient artifact than ye know, but in order ta reveal its secrets, we need ta get it to the Cradle of the Ancients!\n\nNow howdya spose we do that?\n\nMaybe junior over there has some bright ideas, eh?", completion = "Of course I have a plan for moving the coffer.\n\nSomeday, maybe the old coot will learn to trust me.", objectives = "Speak to Harrison Jones at the Temple of Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28622] = { id = 28622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Three if by Air", description = "I had planned on bringing the coffer back to my lab for study, but it seems Brann here has different ideas.\n\nHe thinks he knows how to put a stop to Deathwing's plans here in Uldum.\n\nMy buddy, Jock, is standing by with the transport, just waiting for our signal.\n\nTake these flares and plant them around the perimeter to let him know that we're ready.", completion = "Nice work, lad.\n\nLooks as tho everything made the trip in one piece.\n\nI'm beginnin' ta see why junior keeps ye around.", objectives = "Use the Signal Flares at the Temple of Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28623] = { id = 28623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Push Westward", description = "Our work is done here, {name}.  Against all odds, we stopped the Neferset advance on Nahom.\n\nLet us join the forces pushing west, lest they take all the glory for themselves.\n\nThey must've reached the outskirts of Neferset City by now.", completion = "You've arrived just in time, {name}.", objectives = "Report to King Phaoris at the Neferset City Outskirts in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28624] = { id = 28624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kilram's Boast", description = "Pah! Crude and clumsy is all I see!\n\nYou need more than just strength. My axes are just as strong as Lilith's maces, but so sharp, I can cut through a tree in one chop!\n\nYou heard me, one chop! I'll prove it, too, here in front of everyone. Go ask Deez if he can get a tree in here!", completion = "They want a tree now? Let's see what I got.", objectives = "Speak with Deez Rocksnitch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28625] = { id = 28625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chop Chop", description = "I deal in small timber plenty, but full trees? That's a novelty item. Kinda like those boulders.\n\nMaybe you can do me another favor. Just west of town there's a grove of trees overlooking Lake Kel'theril. I don't know if it's the spooks there, or all that elf magic junk strewn around the place, but we've been getting treants and lashers wandering around there recently.\n\nThey're making it a real pain to chop wood over there, so why don't you chop some of them? Bring the wood from the treants back here.", progress = "Show me the lumber.", completion = "Not a bad haul. Maybe we should look into growin' those treants instead...", objectives = "Collect 10 pieces of Fresh-Cut Frostwood from Frostleaf Treants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28626] = { id = 28626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tree Delivery", description = "Here you go, one instant Super-Gro Insta-Tree made with 80% natural ingredients!\n\nNo roots, no muss, no fuss. Just give it to Kilram and make sure he stands the heck back when he uses it.", progress = "Chop chop!", completion = "Alright! Stand back now and watch what a true quality weapon can do!", objectives = "Deliver the Super-Gro Insta-Tree to Kilram at the inn in Everlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28627] = { id = 28627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seril's Boast", description = "Brutes and amateurs.\n\nIt doesn't matter how sharp or heavy your weapon is if all it's good for is hacking like an ogre. I could go on and on about finesse and speed and balance and control... but it's easier to one-up these fools.\n\nTell Deez we've got one more order for him. I need a block of ice.", completion = "Oh, it's you again! I'm so surprised!", objectives = "Speak with Deez Rocksnitch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28628] = { id = 28628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ice Delivery", description = "Alright, one high-quality, pure grade Instant Ice Block!\n\nI tried selling these to people for protection for a while. Y'know, like that trick you see mages pull? Couldn't figure out the whole \"breathing\" thing, though.", progress = "Ah, you're back!", completion = "Perfect. Now you'll see what really matters in a weapon... finesse.", objectives = "Deliver the Instant Ice Block to Seril Scourgebane in Everlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28629] = { id = 28629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Are We There, Yeti?", description = "My friends are always coming up with great ideas. I've never felt like I could match them... until today! I just drew up the plans for something great! If you promise not to tell, I'll let you in on the secret... \n\nI'm going to make a mechanical yeti! Not only are my friends sure to be freaked out when they see it, but when they get over that, I know they'll be impressed!\n\nI need thick yeti fur from the Ice Thistle yeti. There's plenty of them in the Ice Thistle Hills to the southeast.", progress = "I've got lots to get started on here. Please get me those furs as soon as you can!", completion = "These furs are perfect, {name}. We're off to a great start here!", objectives = "Collect 10 Thick Yeti Furs from Ice Thistle Yeti.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28630] = { id = 28630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo Three", description = "A lot of goblins have been going missing out there in Ice Thistle Hills. I was almost one of them!\n\nI had the idea to set up a sensor to tell us when the yeti were getting close to Everlook. Of course, it's not working either. There's yeti all over the hills and I haven't heard a peep from it.\n\nWould you mind checking on it for me? It might still be fixable. Echo Three's set up to the southeast on the edge of Ice Thistle Hills. Don't ask what happened to Echo One and Two.", completion = "Part of this machine is still moving, but on closer inspection it's been severely manhandled. The metal is dented and cracked, and there's huge footprints in the snow all around it.\n\nIn fact, it sounds like something's approaching right now...", objectives = "Find Echo Three.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28631] = { id = 28631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Horns", description = "I can't make a yeti without horns!\n\nI've been looking for what seems like forever for the perfect set of horns... and no horn I find is good enough! But just the other day I saw the biggest yeti in Winterspring.\n\nI named him Icewhomp. His horns are the ones I've been looking for! He lurks all the way in the back of the cave along the eastern ridge of Ice Thistle Hills.\n\nBring me his horns... but be sure to check on Echo Three along the way!", progress = "Are they perfect? They better be perfect!", completion = "I can't wait to show my friends! Now, just wait a moment while I attach these...\n\nPerfect!", objectives = "Obtain Icewhomp's Pristine Horns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28632] = { id = 28632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh From The Hills", description = "Ice this time? Hoo boy, sure. I've got good news and bad news for you.\n\nThe good news is there's a bunch of pure solid ice over in the Ice Thistle Hills cavern, straight east from Everlook. The bad news is there's also a bunch of vicious yetis in there.\n\nBut if you can handle the yeti, hey, piece of cake! Just walk right up to the bigger chunks and crack 'em open with your weapon. Bring it all back to me and I'll do my thing.", progress = "Oh, you're back! How were the yetis?", completion = "Not bad! Let's hope they don't ask for lava or something next, right?", objectives = "Collect 7 Pieces of Pure Glacier Ice from the cavern in Icethistle Hills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28633] = { id = 28633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Coffer of Promise", description = "I'm not quite certain what ta expect 'ere, so stay on yer toes, eh?\n\nThese codes should reveal the coffer's true purpose, and present us with the tools to thwart Deathwing's efforts in Uldum fer good!\n\nStand back!", progress = "Well, now.\n\nWould ya look at that!?", completion = "Of course! I had a hunch this is what we'd find.\n\nHad no idea about the organic transformations, though, I must admit.\n\nThere's more to this old relic than I'd dared to hope.", objectives = "Give Brann Bronzebeard the contents of the Coffer of Promise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28634] = { id = 28634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extinction", description = "Owlbeasts... Soulless, feathered monstrosities sent from the darkest depths of the Twisting Nether to prey upon the weak.\n\n<Nils points to the woods surrounding Eastpoint Tower.>\n\nThey surround us on all sides and they are planning an attack - I can sense it. You must stop them before they can organize.\n\nI want you to head into the forest and kill every owlbeast that you see. NONE SHOULD SURVIVE!", completion = "The itching has stopped - for now - but they will return.\n\nOh yes, they will return...", objectives = "Kill 12 Rampaging Owlbeasts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28635] = { id = 28635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Haunting in Hillsbrad", description = "The battle over Dun Garok was the bloodiest of all the Hillsbrad battles. The dwarves, outnumbered ten-to-one, fought until the bitter end. Every last one of 'em died in defense of that piece of land.\n\nNow I hear claims that the place is haunted. Nobody wants to go near it! Unfortunately I have orders to prepare Dun Garok for habitation.\n\nCould you do me a favor and go to Dun Garok and search for evidence of a haunting? It's far to the southeast.", progress = "OoooooOooooo...", completion = "Haunted? Ye could say that!", objectives = "Search Dun Garok for evidence of a haunting.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28636] = { id = 28636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silence of the Dwarves", description = "The spirits of my soldiers haunt this fort now, <lad/lass>. Their souls are now bound to this place. Even in death they continue to fight for it. 'Tis sad.\n\nPut 'em out o' their misery and perhaps ye shall have the spoils of yer people's victory.", completion = "They fight for their land even after death - much like the Forsaken. I will report back to high command that Dun Garok is uninhabitable. Let them keep what they hold so dear.", objectives = "Kill 10 Dun Garok Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28637] = { id = 28637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste for Bear", description = "Have you ever had the luxury of trying bear meat? I never had the chance to try it in Gilneas, but the bears here are simply exquisite.\n\nThe shardtooth bears that roam just to the south are well-marbled with fat from the cold here. I've been hunting them myself, and it's quite a lark, but I much prefer eating them!\n\nI recommend you try your hand at the hunt. Stick to the white-pelted shardtooth bears, and the Captain will go to field to bring back any you kill.", completion = "Simply splendid! I've been watching the Captain bring bear after bear back to camp and I can't wait to see them thrown on the smoker.\n\nPerhaps I'll have a taste of them raw...", objectives = "Kill 15 Shardtooth bears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28638] = { id = 28638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Owls Have It", description = "I've been eatin' owls my whole life. Owls is good eatin', and my friend Jez agrees. I was the first one that told him to sell owl!\n\nMister fancy-pants worgen here says bears taste better, but don't pay him no mind. You should go hunt yourself some owl. There's plenty of 'em wandering just south of here. Stick to the gray ones for now, an' buzz me on the little talky-thing Jez gave you when you've racked up a few.", objectives = "Slay 15 Winterspring Owls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28639] = { id = 28639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursius", description = "I've heard it said that you are what you eat. I don't know if I believe that, but if it's true... I'd prefer to eat the strongest creature that I can find.\n\nUrsius is the largest bear in Winterspring. He eats first when his pack of shardtooth brings down a chimaera or an owlbear. He claims the most comfortable cave in the shardtooth-held lands. And he has... considerable influence with the shardtooth females.\n\nHe is my kind of bear.\n\nI want to eat him.\n\nHis cave is near the maulers. Good luck!", completion = "Ursius is... not delicious.  He tastes like a combination of pinecones and curdled milk, only... oilier.\n\nAre you sure this is Ursius?  The big bear?  In the cave?\n\nThis is horrible.  It honestly tastes like his meat has been steeped in urine.\n\nI don't feel like I'm getting any stronger.\n\nUgh.  It's really bad.  Do you want to try some?", objectives = "Kill Ursius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28640] = { id = 28640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh Frostsabers", description = "Doesn't that smell great? My smoked meats get top dollar, and nobody else provides the exotic flavors I've got out here in the hills. And it's efficient; you just do the hunting for a small fee, and my other fine friends drag the beasts back here for skinnin' and smokin'!\n\nI've got the market cornered on Frostsaber meat right now. Absolutely delicious stuff, makes great sausages. Head out and hunt those cats just west of here, and we'll call that a start!", completion = "Alright! Don't stop now, we're after the big ones next!", objectives = "Slay 15 Frostsabers or Frostsaber Stalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28641] = { id = 28641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pride of the Dinner Table", description = "Alright kid, time to head out further into the field!\n\nThis haul's nice and good, but further to the west you'll find much bigger kitties. The pride watchers and huntresses have a lot more muscle on them, and it makes AMAZING burger patties. They sell like crazy!\n\nGimme a ping when you've cleared house and we'll see about you going after the main course.", completion = "Beautiful! I'm watching the Captain drag this all back right now and it's a gorgeous sight.\n\nAnd the next course...", objectives = "Slay 15 Frostsaber Huntresses or Frostsaber Pride Watchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28642] = { id = 28642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shy-Rotam", description = "In northern Winterspring, great cats assemble around a large landmark called Frostsaber Rock. The leader of these cats is known by the name Shy-Rotam. Defeating the matriarch of the frostsabers would grant you much respect in the eyes of your fellow {race}.\n\nGo again to the harsh wilds, and once there, gather sacred meat from the frostsabers. Find the stone of Shy-Rotam, and place it there. Placing the meat of her kin before her will summon Shy-Rotam, in anger.\n\nBe ready for her fury, and defeat her.", objectives = "Storm Shadowhoof at Everlook in Winterspring wants you to defeat Shy-Rotam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28643] = { id = 28643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Durnholde Challenge: Zephyrus", description = "Durnholde Keep has always been a place of strife. For years the humans used it as an internment camp and prison for the orcs. After that it was taken over by the Syndicate. Now? The Dark Lady captured and placed powerful elementals within its walls. She charged me with administering \"The Durnholde Challenge.\" Any that can defeat all of the elementals will earn a grand prize! Take this guide and face your first challenge: Zephyrus!\n\nDurnholde is located just northeast of us.", completion = "Zephyrus was a mighty adversary. Surely the remaining elementals will challenge you further!\n\n<You open the guide that Jekyll gave to you.>", objectives = "Kill Zephyrus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28644] = { id = 28644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Durnholde Challenge: Teracula", description = "According to the guide, Teracula is your next challenge. It roams the path just outside of Zephyrus' lair.", completion = "Teracula was an even mightier adversary than Zephyrus.\n\n<You open the guide that Jekyll gave to you.>", objectives = "Kill Teracula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28645] = { id = 28645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Durnholde Challenge: Bloodvenom", description = "According to the guide, Bloodvenom is your next challenge. The fearsome elemental can be found on the lower level of Durnholde Keep, near the western prisons.", completion = "Now you know why the monster was called Bloodvenom. What challenges remain?\n\n<You open the guide that Jekyll gave to you.>", objectives = "Kill Bloodvenom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28646] = { id = 28646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Durnholde Challenge: Infernus", description = "According to the guide, Infernus is your next challenge. This being, made of molten lava and raging fire, can be found on the lower level of Durnholde Keep, near the eastern prisons.", completion = "Though you have defeated the four elements, one final challenge awaits. What could it be?\n\n<You open the guide that Jekyll gave to you.>", objectives = "Kill Infernus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28647] = { id = 28647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Durnholde Challenge: D-1000", description = "Imprisoned in the old Durnholde Keep arena is a being comprised of pure mercury. The Forsaken have dubbed it the D-1000. Kill the D-1000 and claim your prize!", completion = "This is the first time anyone has actually completed the challenge. You truly are a powerful {class}, {name}. As promised, choose your reward.", objectives = "Kill the D-1000.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28648] = { id = 28648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frak's Wild Ride" }
quests[28649] = { id = 28649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty worgen in there that I think you'll take great pleasure in executing.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", objectives = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Lord Harford, an Argent Dawn prisoner inside the nearby prison house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28650] = { id = 28650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty goblin in there that I think you'll take great pleasure in executing.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, {name}. You're Scourge. You're one of us. Forever...", objectives = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Gally Lumpstain, an Argent Dawn prisoner inside the nearby prison house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28651] = { id = 28651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Novice Elreth", description = "Why don't you go speak with my novice, Elreth?  She serves me, and will have some tasks to which you can apply your new abilities.", completion = "May the Dark Lady watch over you, {name}.", objectives = "Speak to Novice Elreth at Deathknell in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28652] = { id = 28652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caretaker Caice", description = "I am done with you.  There are, however, others who can use your aid.\n\nCaretaker Caice, standing on that stump behind me, can probably give you another assignment.  You should speak with him now.", completion = "Yes?  And who might you be?", objectives = "Speak with Caretaker Caice at the Deathknell Graves in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28653] = { id = 28653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Priest Sarvis", description = "Are you still here, {name}?  You know, I'm only a deathguard.  I don't have many tasks I can hand out to passers-by like you.\n\nI'd recommend that you talk to Shadow Priest Sarvis.  I remember, he helped me get on my feet after I was plucked out of that tomb.  I'm sure he'll do the same for you.\n\nYou'll find him just inside the chapel, here on the west side of town.", completion = "Greetings, {name}.\n\nI see you wield a weapon.  Can you fight?", objectives = "Speak with Shadow Priest Sarvis at Deathknell in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28654] = { id = 28654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Matter", description = "Well, <laddie/little lady>, half of me wishes I could stick around a while and take in the sights with ye.\n\nI've seen some mighty amazin' things in my day, but this here takes the cake.\n\nSadly, I have a fair bit o' research ta do on these discs before I make my way into the Halls of Origination.\n\nYou seem ta be worth your salt, perhaps ye'd like ta tag along and see how a REAL archaeologist works, eh?", completion = "Bout time ye showed up, lad.\n\nNow let's get goin'! There be work ta do!", objectives = "Brann Bronzebeard wants you to meet him in the Halls of Origination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28655] = { id = 28655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild, Wild, Wildhammer Wedding", description = "We are ready to begin, {name}!\n\nBut I have it on good authority that the Twilight's Hammer may try to disrupt the ceremony, so as to demoralize and destroy the Wildhammer. Things could get dangerous!\n\nFor this reason, I will be performing the ceremony myself, so that I can keep the bride and groom close to me. Sound like a plan? Good!\n\nSince her father is dead and her brother the best man, Fanny has asked that you walk her down the aisle. What an honor! Talk to me when you're ready to begin.", progress = "It's a nice day for a Wild wedding...", completion = "We did it, {name}! Fighting that ... thing side-by-side really brought all the Wildhammers together. The heads of the families are more united than I've ever seen them. Drink up, {name}, and celebrate!!\n\nOf course, our work is only beginning. I'll rally our new Wildhammer reinforcements with the rest of the Alliance and prepare to storm the Twilight Bastion.\n\nI'm sure we'll meet again soon.", objectives = "Talk to Grundy MacGraff to begin the wedding ceremony. Kill any Twilight's Hammer that try to stop it!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28656] = { id = 28656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Life Forces", description = "When this creature died, some sort of energy was released from its body. The energy was passed on to you, and now you feel somewhat stronger.\n\nAccording to Winterspring locals, Witch Doctor Mau'ari at the Snowden Chalet is an expert in the wildlife of the area. She might know something about this mysterious energy.", completion = "What's dis? You got de smell of de E'ko on ya! Let Mau'ari tell ya a little bit about de E'ko and what it do.\n\nYou're lucky, {race}. De E'ko searched you out. A troll like me's gotta go find de E'ko herself.\n\nAll de creatures of Winterspring have E'ko. De furbolg, de chillwind, de shardtooth... even de Ice Thistle yeti! You kill dese creatures, and sometimes, a bit of E'ko comes out. Different creatures... different E'ko.\n\nGo on now. Go find de other E'ko!", objectives = "Speak with Witch Doctor Mau'ari at the Snowden Chalet in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28657] = { id = 28657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Huge Problem", description = "We finally capture this godforsaken rock and then we find out that there is a huge ettin roaming around, taking out our sentry patrols!\n\n{name}, I need you to round up a few friends and take that ettin down.  We can't have a beast like that roaming around, wreaking havoc.\n\nStay alert, reports from the front say that he is carrying a huge tree as a weapon, and he is not afraid to use it.", progress = "Did you find problim yet?  Pretty hard to miss that guy with how huge he is.", completion = "You actually killed him?!  I can't believe it!", objectives = "You have been asked to kill Problim, a giant ettin that roams the paths of Tol Barad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28658] = { id = 28658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swamp Bait", description = "Supplies are never easy to find in a place like this, {class}.  We have been scouting since we captured the island but things are not looking good.\n\nFortunately, we just  received a scouting report that a swamp full of crocs is just west of our base camp here.  The hides off those crocs will come in handy for our leatherworkers.  Bring back as many as you can.", progress = "You cleared out that swamp yet?", completion = "Looks like you were able to get the croc hides that we needed.  Thanks {name}, your contributions will not go unnoticed.", objectives = "You have been tasked with collecting 8 Crocolisk Hides from the Baradin Crocolisks on Tol Barad. The crocolisks can be found in the swamp, just west of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28659] = { id = 28659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Leftovers", description = "We fought hard to capture this island, {race}.  We cleared out most of the Alliance filth but I can still smell their foul stench in the air.\n\nI need you to investigate the slagworks, warden's vigil and the ironclad garrison.  Kill any Alliance that you find.\n\nYou know what they say, the only good Alliance is a dead Alliance!", progress = "Gah, the smell of their weak bodies is sickening me.", completion = "Those filthy alliance never stood a chance.  Nice work, {name}.", objectives = "You have been instructed to kill 12 Alliance Infantry on Tol Barad. You can find the holdouts in The Slagworks, Warden's Vigil and the Ironclad Garrison, here on Tol Barad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28660] = { id = 28660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Depths", description = "You are a sight for sore eyes, {name}.  Now that we have claimed tol barad, the battle has just begun.\n\nWe discovered a cell block just east of here that we need you to clear out.  Turns out that its chock full of ghosts that have been locked up down there for who knows how long.\n\nClear out as much as you can and report back to me when you are done.", completion = "You made it back out alive?  You are a stronger man than I, {name}.", objectives = "You have been asked to kill 9 ghosts of any type in the Cursed Depths, just east of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28661] = { id = 28661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Imprisoned Archmage", description = "We have been trying to clear out the Cursed Depths cellblock since we landed on Tol Barad.  It seems that everytime we get close, that archmage shows up and pushes us back.\n\nNow that we have claimed the island, it's time we take another shot.  Head down there and bring me back his staff as proof that you have finished the job.", progress = "Have you been able to take out the Archmage?", completion = "Galus is dead?  Fantastic work {name}, now we can send down the cleanup crew and get that cellblock ready for new prisoners.", objectives = "You must kill Archmage Galus and return with his Staff from the Cursed Depths, just east of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28662] = { id = 28662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning From The Past", description = "Now that we finally have a hold on this wretched island, we can start to investigate how it got in this condition.  Some of our troops have discovered journals around the entrance to Cursed Depths cellblock just east of here.\n\nThese journals are of particular interest to our elder scribes back at base camp.  I need you to recover four of them and bring them back to me as fast as you can.\n\n{name}, be careful down there, that place is crawling with undead.", progress = "Were you able to recover the journals?  Reports mentioned that they were sighted both in and out of the cells down there.", completion = "These journals are in excellent condition {name}.  We will begin deciphering them immediately.  Only time will tell what secrets they hold.", objectives = "You have been asked to recover four Dusty Prison Journals from the Cursed Depths, just east of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28663] = { id = 28663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "D-Block", description = "Have you heard of the D-Block yet {name}?  It's one of the old cellblocks here on the island.  Problem is, it's infested with demons.  We planned on using it to lock up the leftover Alliance we found on the island, but that is not going to happen in its current state.\n\nI need you to head down there and clear those demons out.  Report back to me when you are done.", completion = "D-Block is all clear?  Good work, {name}.  We will send down a crew to start cleaning up right away.", objectives = "You have been instructed to kill 10 demons of any type in the D-Block, just northwest of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28664] = { id = 28664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Svarnos", description = "Excellent work on the island capture, {class}.  Now that we have claimed the island, we need to make these cellblocks useable for prisoners.  D-Block has been especially hard to clear out.  Unfortunately it has become overrun with demons of all sorts.\n\nWe have been able to thin out the demons but a large core hound has broken its way out of its cell and is wreaking havoc down there.  I need you to kill him and bring back his collar.", progress = "Is the core hound dead?", completion = "Svarnos is finally dead?  Looks like we can finally get to work setting up that cellblock then.  Thank you {name}.", objectives = "You must kill Svarnos in the D-Block and return with his Cursed Collar. Svarnos can be found in the D-Block, just northwest of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28665] = { id = 28665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cursed Shackles", description = "Have you been down in the D-Block yet, {name}?  Every time we clear that infested cellblock out, the demons seem to return rather quickly.  We learned that they regenerate from the cursed shackles scattered around the area.  That's where you come in to the picture {name}.\n\nI need you to retrieve as many of those shackles as you can and bring them back to me.  We will destroy them immediately.", progress = "Did you find many shackles?  Reports mentioned that they were all over the place down there.", completion = "The shackles!  We will begin the process of destroying these shackles immediately {name}.  Thank you for your help.", objectives = "You have been asked to recover 8 Cursed Shackles from the D-Block, just northwest of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28666] = { id = 28666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Burning Steppes!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to John J. Keeshan at Flamestar Post.\n\nYour aid is urgently needed to put an end to the Blackrock orc menace!\n\nYou can reach the Burning Steppes by traveling south from the Searing Gorge through Blackrock Mountain. Look for Flamestar Post on the far side of the mountain.\n\nFor the glory and honor of the Alliance!", completion = "It's time for the Blackrock orcs to feel the full wrath of the Alliance. They will pay for what they've done.", objectives = "Report to John J. Keeshan at Flamestar Post in the Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28667] = { id = 28667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Burning Steppes!", description = "All able bodied members of the Horde are hereby ordered to report to Ariok at Flamestar Post.\n\nHonored Eitrigg's son, Ariok, needs your assistance to halt the blind aggression of the Blackrock orcs before they invade the neighboring lands.\n\nYou can reach the Burning Steppes by traveling south from the Searing Gorge through Blackrock Mountain. Flamestar Post will be south of the mountain.\n\nDestiny calls!", completion = "We must stop the Blackrock orcs before they can expand their influence.", objectives = "Report to Ariok at Flamestar Post in the Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28668] = { id = 28668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prison Revolt", description = "We have the island, now we need to put the resources here to work.  We found an abandoned cellblock just southwest of here and we need you to go check it out {name}.\n\nReports have come back that it is overrun with prisoners that have been stuck down there for years.  Do whatever you need to do to clear that place out.  Report back to me when you are done.", completion = "You cleared that area out?  Looks like you might be more useful to us that we thought, {race}.", objectives = "You have been instructed to kill 10 prisoners of any type in The Hole, just southwest of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28669] = { id = 28669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden", description = "We have almost finished clearing out the revolting prisoners in the hole, but one last problem remains.  The warden.\n\nWarden Silva is their master and they will do anything for him.  If we take him out, we take them all out.  Finish him off and bring me back his keys.  We can use those keys to explore deeper into the cellblock and possibly gain access to the water supply here on the island.", progress = "Is the warden dead yet?", completion = "Ahh, the wardens key's.  Another job well done, {name}.  These will come in very handy.", objectives = "You must kill Warden Silva in The Hole and return with his keys. The Hole is just southwest of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28670] = { id = 28670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Food From Below", description = "Supplies are running low here in camp, {name}.  We have recently learned that the cellblock just southwest of here has a number of rations remaining from years of use.  We need you to gather as many of those as you can and bring them back to camp.\n\nOne more thing, the entire cellblock is overrun with prisoners so be careful.", progress = "Were you able to recover the rations?  Reports mentioned that they could be found all over the place down there.", completion = "These rations will really help the troops out {name}.  Thank you for your help.", objectives = "You have been asked to recover 12 Cellblock Rations from The Hole, just southwest of Baradin Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28671] = { id = 28671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Blasted Lands!", description = "All able bodied members of the Horde are hereby ordered to report to Okrilla at Dreadmaul Hold.\n\nOkrilla, commander of the Horde forces at Dreadmaul Hold, requires your help to secure the outpost against rebellious ogres and the forces of the Alliance.\n\nTravel to Dreadmaul Hold by taking the road south from the Swamp of Sorrows.\n\nDestiny calls!", completion = "Our enemies are numerous, {class}. It will take skill and bravery to overcome them all.", objectives = "Report to Okrilla at Dreadmaul Hold in the Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28672] = { id = 28672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Executor In the Field", description = "I can keep you busy here in town all week... but you seem to be more the fighting type.\n\n<Elreth looks you over and nods.>\n\nYes, you'll do just fine.  I'd like you to go talk to Executor Arren.  Follow the path north, out of Deathknell.  You'll find him not far past the barricades.", completion = "What do we have here?  A new {class}, ready for battle, eh?", objectives = "Report to Executor Arren.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28673] = { id = 28673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Blasted Lands!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Quartermaster Lungertz at Nethergarde Keep.\n\nNethergarde's garrison urgently needs your help to stem the Horde advance into the Blasted Lands! Travel south from the Swamp of Sorrows and follow the road east to reach Nethergarde Keep.\n\nFor the glory and honor of the Alliance!", completion = "For decades has the garrison at Nethergarde held firm against the threat of the Horde and we do not intend to surrender now.", objectives = "Report to Quartermaster Lungertz at Nethergarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28674] = { id = 28674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starfall Village", description = "You've been pretty busy around here. If you're still eager to do good deeds, or just get paid, I've got something you might be interested in.\n\nStarfall Village is just northwest of Everlook. The night elves there recently suffered a pretty nasty bug infestation, and they're asking for any help they can get.\n\nA few goblins from here already went there to start exterminating, but I'm sure there's room for more. Talk to Wynd Nightchaser, he'll fill you in.", completion = "Welcome to Starfall, {class}. We have opened our doors to all travelers in our time of need.", objectives = "Speak with Wynd Nightchaser at Starfall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28675] = { id = 28675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Swamp of Sorrows!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Trade Baron Silversnap at Bogpaddle.\n\nThe Alliance forces urgently needs the munitions provided by the baron! You must do whatever is necessary to convince the baron to keep selling our forces supplies at reasonable prices.\n\nTo get to the swamp, follow the road from the southeastern Burning Steppes through the Redridge Mountains.\n\nFor the glory and honor of the Alliance!", completion = "Welcome to Bogpaddle, {class}. I fully expect you will enjoy all our facility has to offer.", objectives = "Report to Trade Baron Silversnap at Bogpaddle in the Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28676] = { id = 28676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exterminators at Work", description = "The infestation of our barrow den occured nearly overnight. Vicious creatures never before seen in these lands swarmed the tunnels, hatching from unseen eggs.\n\nWith the few of us here, it was all we could do to keep them from spreading outside the den. We were forced to hire goblins from Everlook that claimed expertise in extermination, but they have not yet been successful.\n\nIf you wish to assist them, enter the barrow den to the west of this lodge and speak with Rinno Curtainfire.", completion = "Oh good, another warm body!\n\nI hope that elf up there didn't bore you to death. We've got a lot of bugs to kill here.", objectives = "Speak with Rinno Curtainfire inside the Ban'Thallow Barrow Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28677] = { id = 28677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Swamp of Sorrows!", description = "All able bodied members of the Horde are hereby ordered to report to Trade Baron Silversnap at Bogpaddle.\n\nPersuade the trade baron to continue supplying our warriors with the weapons and munitions they require, no matter what it takes!\n\nTravel to the Swamp of Sorrows by following the road from the southeastern Burning Steppes through the Redridge Mountains and meet the trade baron at his seaside resort.\n\nDestiny calls!", completion = "Welcome to beautiful Bogpaddle!", objectives = "Report to Trade Baron Silversnap at Bogpaddle in Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28678] = { id = 28678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain P. Harris", description = "The Cape of Lost Hope has been a sore in our side for weeks here on Tol Barad.  Half of our supply ships end up on the rocks down there.\n\nTo make matters worse, it's been overrun by a gang of undead sailors.  We have tried thinning the ranks, but they just seem to keep coming back.  Our last resort is to try and take out the captain that they report to.  You should be able to find him on a ship, just off the shoreline.\n\nOh, and I hope you are not too scared of sharks.", completion = "You did it!  Maybe we can finally get some ships into port now.  Thank you {name}.", objectives = "You have been tasked with killing Captain P. Harris at the Cape of Lost Hope. The Cape of Lost Hope can be found northwest of here, along the coast. Just look for the shipwrecks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28679] = { id = 28679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rattling Their Cages", description = "We have been having issues with the undead down at the Cape of Lost Hope for a while now.  Every time a new ship wrecks, they end up getting more undead to join their ranks.\n\nCan you do us a favor and thin out the ranks up there?  I know you won't be able to kill them all, but anything you can do will help at this point.\n\nKeep an eye out for alliance, we have been getting reports of them ambushing the beach lately.", completion = "Nice work on the undead up there {name}.  We really appreciate the help.", objectives = "3rd Officer Kronkar has asked you to kill 8 Shipwrecked Sailors at the Cape of Lost Hope. The cape is located due northwest of here, on the beach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28680] = { id = 28680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boosting Morale", description = "Morale is low these days, {name}.  We make every effort we can to keep the troops in high spirits but we are running low on our main supply of morale booster... rum.\n\nI have been getting reports from our infantry to the south that the shipwrecks on the Cape of Lost Hope still have a good supply of southsea rum in their wrecked hulls.  Can you head up there and investigate?\n\nBring back any rum you can find.", progress = "Were you able to recover the rum?  I would try but I am deathly afraid of the water.  Not to mention that crazy shark.", completion = "This rum will really help us out, {name}.  They might not feel great in the morning but at least they will go to sleep happy.", objectives = "You have been asked to recover 6 Barrels of Southsea Rum from the shipwrecks on the Cape of Lost Hope. The cape can be found north of here, along the coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28681] = { id = 28681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shark Tank", description = "I hate sharks.  All of my troops hate sharks too.  This is where you come in, {name}.\n\nI need you to head up to the Cape of Lost Hope and take out a huge shark named Tank.  Tank is not to be trifled with so I would bring a few friends if I were you.", completion = "No way, you actually killed him?  We are having shark tacos tonight for sure!", objectives = "You have been tasked to kill Tank, a large shark cruising the waters of the Cape of Lost Hope. The cape can be found north of here, along the northern coastline.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28682] = { id = 28682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claiming The Keep", description = "Have you seen the keep on the north side of the island, {name}?  That is where Keep Lord Farson runs his operation from.\n\nFarson has a small group of dedicated followers and they have been giving us trouble since we got here.  We sent a small group to investigate and they reported back on his exact position within the keep.\n\nCan you finish him off for us?", completion = "You killed him?  We have been trying to take that guy out for weeks!  We thank you, {name}.", objectives = "You have been asked to kill Keep Lord Farson at the Farson Hold. Farson Hold can be found on the north side of the island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28683] = { id = 28683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thinning the Brood", description = "We have been trying to get a foothold in The Darkwood for weeks now but that forest is infested with spiders.  Do me a favor and see if you can thin them out enough for us to set up an attack.\n\nCareful out there, I have heard reports of Alliance troops nearby earlier in the week.", completion = "Nice work on those spiders {name}.  At this rate, we will be taking that forest in no time.", objectives = "Kill 12 Darkwood Lurkers in The Darkwood. The Darkwood forest is just north of here, across the bridge on the central island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28684] = { id = 28684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sticky Task", description = "Finding supplies on the island has been difficult, to say the least.\n\nFortunately, we have found a good supply of silk in The Darkwood, just north of here.  The bad part of this story is that the silk comes from the glands on Broodmother spiders.  I need you to gather 4 of these for me.\n\nThat should be just enough to finish up this last set of shirts.", progress = "Were you able to gather the sticky silk glands?", completion = "These glands will do nicely.  We are grateful for your help, {name}.", objectives = "Collect 4 Sticky Silk Glands from Darkwood Broodmother spiders in The Darkwood. The Darkwood forest is just west of here, across the bridge on the central island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28685] = { id = 28685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave No Weapon Behind", description = "Battle supplies are hard to come by on this rock.  Every time we hold off another Alliance attack, it feels like we are fighting with sticks and stones.\n\nReports have come in that Keep Lord Farson on the north side of the island has a large stockpile of rifles that we could use.  Can you head down there and check it out?\n\nBe careful {name}, Farson's followers will do anything to protect him.", progress = "Any luck with those rifles?", completion = "Thanks for rounding these up for us, {name}.  Kind of hard to fight a battle without any guns.", objectives = "Retrieve 12 Rusty Rifles from Farson Hold on the north side of Tol Barad Peninsula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28686] = { id = 28686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not The Friendliest Town", description = "Have you been up to Rustberg Village yet {name}?  I would suggest you bring a sharpened blade if you are heading that direction.\n\nThe folks in that town look alright but something suspicious is going on in there.  Reports have been coming in that they are picking off our soldiers left and right.  We have had just about enough of that, so I need you to head down there and do a little cleaning house for us.\n\nTake down as many as you can and report back when you are done.", progress = "Did you find out what's up with that village?  Something seems off...", completion = "Told you that village was full of wackos.  Nice job clearing it out {name}.", objectives = "Commander Larmash has asked you to kill 14 villagers in Rustberg Village. Rustberg Village is just north of base camp, on the right side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28687] = { id = 28687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teach A Man To Fish.... Or Steal", description = "Rustberg Village.  That place is a curse and a blessing for us, {name}.  I have no clue where bandits learned to fish as well as they do but I have no time to worry about that now.\n\nI need you to head down there and steal as many of their fish reserves as possible.  We have been living off scraps since we retook the island and this is our best chance at some solid food reserves.\n\nKeep an eye out for stealthers up there, reports have told us they are prevalent inside the village walls.", progress = "Were you able to pull off the heist and get us some fish?", completion = "These fish will do nicely, {name}.  Keeping the troops fed and in good condition is our number one priority and you really came through for us here.", objectives = "You must steal 22 Rustberg Seabass from Rustberg Village. The fish can be found on string stands at the docks, round back of the village. Rustberg Village is due north of base camp, on the right side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28688] = { id = 28688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Northern Stranglethorn!", description = "All able bodied members of the Horde are hereby ordered to report to Commander Aggro'gosh at Grom'gol Base Camp. The commander requires your aid to keep the supply routes open and free of interference from the local inhabitants and the troublesome Alliance.\n\nTo reach Grom'gol, you can take the zeppelin from Orgrimmar's eastern zeppelin tower or the one near Undercity.\n\nDestiny calls!", completion = "At last, the Warchief's reinforcements have arrived.", objectives = "Report to Commander Aggro'gosh at Grom'gol Base Camp in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28689] = { id = 28689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forgotten", description = "Many soldiers died on this island {name}.  It is only fair that we pay our respects to them in any way that we can.\n\nI need you to travel to Forgotten Hill, due west of here and release our brothers in arms' tortured souls away from this place.  Do be careful over there, reports of undead have been ongoing in the area.", progress = "Were you able to release our forgotten brothers in arms?", completion = "May their souls rest in peace.", objectives = "Release the spirits of 6 tortured souls at Forgotten Hill. Souls can be channeled by touching your hands directly to the gravestones. Forgotten Hill is due west of here, past The Restless Front.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28690] = { id = 28690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvaging the Remains", description = "Forgotten Hill has been overrun with zombies and ghouls ever since we reclaimed this wretched isle.  We have tried to clear them out many times but they always seem to come back.\n\nOne of our lieutenants recommended taking the ghouls' bones when we kill them in hopes that they can't reincarnate overnight.  Think you can help us out with this one?", progress = "Were you able to recover the femur bones?  Better for you to try than me.", completion = "I didn't think you would be able to do it, {name}.  You are just full of surprises aren't you?", objectives = "You need to recover 9 Cursed Femur bones from the ghouls that inhabit Forgotten Hill. Forgotten Hill is on the west side of the island, just past The Forgotten Front.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28691] = { id = 28691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Lieutenant Connor", description = "The first time I heard about Lt. Connor, I was just a young recruit in Ragefire Chasm.  None of us could believe he ended up here on Tol Barad.  Sadly, he still roams these wretched islands, wreaking havoc on our troops morale.\n\nI need you to put an end to his misery... and ours.", completion = "Hey, you made it back alive!  Can't say you were the first one to try this task, but you are definitely the first one to make it back alive.", objectives = "Find and kill First Lieutenant Connor at Forgotten Hill. You will find Forgotten Hill on the far west side of the island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28692] = { id = 28692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magnets, How Do They Work?", description = "Getting useful machine parts out here on the island has been difficult, {name}.  We have been trying to repair the broken siege engines here in camp but we keep running out of useful parts.\n\nOur second regiment reported some wrecked out siege engines in a old battlefield to the west.  Maybe we could find some parts over there?\n\nYou are going to have trouble finding anything in that old battlefield so take this magnetized scrap collector and put it to some good use.", progress = "Did that magnet contraptaion actually work?", completion = "These parts will really help us out, {name}!  Who would have thought you can find stuff this useful in all that old junk?", objectives = "You have been tasked with recovering 7 pieces of Siege Engine Scrap. Use the Magnetized Scrap Collector in The Restless Front to find the scraps. The Restless Front is due west, just past the second bridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28693] = { id = 28693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finish The Job", description = "We have been trying to collect useful scraps from the front all week.  Every time we gather a batch to bring back to camp, we get assaulted by the restless soldiers in the area.  Can you head over there and clear them out?", progress = "Were you able to finish the job?", completion = "It's about time someone took those guys out.", objectives = "Kill 5 Restless Soldiers at the Restless Front. You can find the front on the west side of the island, just before Forgotten Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28694] = { id = 28694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watch Out For Splinters!", description = "Have you been over to the Wellson Shipyard yet, {name}?  Best to stay away from there unless you have a good reason to venture in.  Unfortunately, that is exactly what I need you to do.\n\nYou see, we have been short on supplies ever since we recaptured the island.  That ghost ridden shipyard is overflowing with lumber but every time we send an escort to recover the lumber, they never make it back.\n\nCan you help us out?", progress = "Did the ghosts scare you off?", completion = "I didn't think you would be able to do it, {name}.  You are just full of surprises aren't you?", objectives = "Private Sarlosk has asked you to recover 15 pieces of Shipyard Lumber from the Wellson Shipyard. The lumber can be recovered from the ghosts in the shipyard or found lying around the premises. The shipyard can be found northwest of here, on the coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28695] = { id = 28695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Foreman Wellson", description = "Foreman Wellson has been a pain in our side since we got here.  His shipyard holds a large amount of supplies that would be extremely useful to us... if we could get to them.\n\nHe keeps a close watch over his minions and makes it very difficult for us to get a foothold on the shipyard.  I need you to take out Wellson for good this time.  Be careful {name}, we have been receiving reports of dirty Alliance all around the area.", completion = "Great work {name}.  I will report your efforts to our highest in command immediately.", objectives = "Kill Foreman Wellson at the Wellson Shipyard. The shipyard can be found north of here, on the western coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28696] = { id = 28696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombs Away!", description = "The Wellson Shipyard is constantly receiving supplies from offshore and we need to put a stop to it.  They have setup cannons along the docks for defense but if you can make it to them, we can use them to destroy their supply ships.\n\nHead down there and see what you can do.  Report back to me on your progress.", completion = "Great work on those supply ships, {name}!  We knew you would be good for somethin' around here.", objectives = "Destroy 10 Ghastly Supply Boats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28697] = { id = 28697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghostbuster", description = "See that hill with the towers to the northeast?  That's Largo's Overlook and it's not a fun place to set up camp next to.  We have been dealing with those spirits and spectres ever since we setup camp.\n\nCan you head up there and let them know we don't plan on leaving anytime soon?  A few good kills on their ranks should put them in line.\n\nThanks for your help on this, {name}.", completion = "Great work, {name}!  We should not hear from the ghosts again anytime soon.", objectives = "Kill 14 ghosts of any type at Largo's Overlook, northeast of the Horde camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28698] = { id = 28698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cannonball!", description = "Largo and his minions have been stealing our supplies ever since we setup camp here.  It's frustrating to say the least.\n\nWe have heard reports that he is stockpiling cannonballs in the towers overlooking the water up on his overlook.  Can you head up there and try to recover some of them for us?\n\n{name}, don't forget to keep a watch out for Alliance too.", progress = "Did you find the cannonballs?", completion = "Good job on the recovery effort {name}. These cannonballs should last us a while.", objectives = "You need to recover 4 Stacks of Cannonballs from Largo's Overlook for Private Sarlosk. You can find Largo's Overlook just northeast of the base camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28699] = { id = 28699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Northern Stranglethorn!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Lieutenant Doren at the Rebel Camp.\n\nYears after Colonel Kurzen's treachery against Stormwind, the truth of what happened remains a mystery. Aid the survivors in learning what became of the colonel. Travel south from Duskwood and follow the road west after crossing into the jungle to reach the Rebel Camp.\n\nFor the glory and honor of the Alliance!", completion = "Welcome to our camp, {class}, such as it is.", objectives = "Report to Lieutenant Doren at the Rebel Camp in Northern Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28700] = { id = 28700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Overlook Back", description = "There is only one way for us to take Largo's Overlook back.\n\nI think you know what we need to do {name}.  Largo is pretty paranoid these days so you should be able to find him on top of the tower, looking for his imaginary navy to finally arrive.", completion = "Ha, we finally got Largo!  Nice one, {name}.", objectives = "Private Sarlosk has asked you to kill Commander Largo at Largo's Overlook. The overlook is just northeast of the base camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28701] = { id = 28701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Harm's Way", description = "Luckily, when the infestation occured, no druids were slumbering in the western barrow den. It is still a sacred site to us, however, and its depths hold blessed relics kept there undisturbed for ages.\n\nWhile I am somewhat trusting of the goblin exterminators, I am also... familiar with the habits of their race. Please retrieve any relics you can find in the barrow den and bring them back to me so they are not damaged. They are within urns, nestled in the small alcoves throughout the den.", progress = "I hope you found them intact...", completion = "They may not look like much to you, but these relics hold great value to the people of Starfall.  You are kind, {name}.", objectives = "Retrieve 5 Starfall Relics from the Ban'Thallow Barrow Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28702] = { id = 28702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: The Cape of Stranglethorn!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Bronwyn Hewstrike at the Explorers' League Digsite.\n\nThe Explorers' League expedition needs your help to safeguard its site and findings from marauding ogres. Travel south from Northern Stranglethorn Vale and follow the road to the Explorers' League Digsite.\n\nFor the glory and honor of the Alliance!", completion = "It's good to see you here, {class}.", objectives = "Report to Bronwyn Hewstrike at the Explorers' League Digsite on the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28703] = { id = 28703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step Into My Barrow", description = "I've still got no clue where all these bugs came from. My best guess is the cataclysm stirred up some underground nests we never knew about.\n\nNo use getting distracted with that when they need killing, though!", progress = "I figured a talented {class} like you would have no problem taking care of a few bugs.\n\nI GUESS I FIGURED WRONG.", completion = "Hey, nice work!\n\nIf you ever want to come back and kill some more bugs for absolutely no additional reward, please, feel free!", objectives = "Kill 10 Coldlurk Creepers and 5 Coldlurk Burrowers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28704] = { id = 28704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: The Cape of Stranglethorn!", description = "All able bodied members of the Horde are hereby ordered to report to Sassy Hardwrench at Hardwrench Hideaway. She requires your help to deal with the pirates and naga who have overrun the jungle.\n\nTravel to Hardwrench Hideaway by heading south from Northern Stranglethorn and looking for the town southwest of the Gurubashi Arena.\n\nDestiny calls!", completion = "Welcome to Hardwrench Hideaway!", objectives = "Report to Sassy Hardwrench at Hardwrench Hideaway on the Cape of Stranglethorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28705] = { id = 28705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Outland!", description = "All able bodied members of the Horde are hereby ordered to report to Lieutenant General Orion at the Stair of Destiny.\n\nYour skills are needed to fight the Burning Legion's presence on the shattered remnants of Outland.\n\nGo to the portal room in Orgrimmar's front gate and talk to the Thrallmar Mage to travel to the Blasted Lands, then walk through the Dark Portal to arrive at the Stair of Destiny.\n\nDestiny calls!", completion = "Prepare yourself for battle. The Horde has need of you here.", objectives = "Report to Lieutenant General Orion at the Stair of Destiny in Hellfire Peninsula.\n\nThe Thrallmar Mage in the Orgrimmar Portal Room can help you get there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28706] = { id = 28706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spray it Forward", description = "My fellow siblings are already further down in the den trying to deal with these bugs, and they're starting to get overwhelmed. I say it's time to gas the place.\n\nTake these fumigators. Don't go setting them off yourself; it takes a highly trained professional, and proper timing. Just find my sisters and pass them out.\n\nRemma should be positioned closest to the entrance. Head down the corridor and  keep to your right once you go down the ramp.", completion = "We're bringing out the bug spray, eh? I guess it can't be helped.", objectives = "Bring the Box of Bugkill Fumigators to Remma Curtainfire inside the Ban'Thallow Barrow Den.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28707] = { id = 28707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spray it Again", description = "I'm gonna start setting this up.\n\nNext one goes to Marcy, further down the den. Head down this corridor here and look for her in the next main chamber.", progress = "Wasn't expecting to see a stranger down here!", completion = "Fumigators? From Rinno? Geez...", objectives = "Bring the Box of Bugkill Fumigators to Marcy Curtainfire inside the Ban'Thallow Barrow Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28708] = { id = 28708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Outland!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Commander Duron in Hellfire Peninsula.\n\nThe expeditionary forces require your help to overcome the demonic armies of the Burning Legion! Talk to the Honor Hold Mage in the tall tower in the Mage District to travel to Blasted Lands, then walk through the Dark Portal to arrive at the Stair of Destiny.\n\nFor the glory and honor of the Alliance!", completion = "The expedition needs your help, {class}.", objectives = "Report to Commander Duron at the Stair of Destiny in Hellfire Peninsula.\n\nThe Honor Hold Mage in the Mage District can help you get there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28709] = { id = 28709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Borean Tundra!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Recruitment Officer Blythe at Valiance Keep in Borean Tundra.\n\nThe Valiance Expedition needs your help to keep the forces of the Scourge under control and safeguard civilized lands! Make your way to the Stormwind Docks and take the ship north to Valiance Keep.\n\nFor the glory and honor of the Alliance!", completion = "The expedition needs your help, {class}.", objectives = "Report to Recruitment Officer Blythe at Valiance Keep in Borean Tundra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28710] = { id = 28710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spray it One More Time", description = "You'd think Rinno could have sent more than a single {race} down here to give us a hand! That freeloader...\n\nI'm gonna set this up. Head north from this room through the corridor and look for Sana. She's probably gotten herself lost in the last chamber, so check the side passages once you get there.", progress = "What're you doing here?", completion = "Rinno sent you! And you brought... fumigators? Ugh!", objectives = "Bring the Box of Bugkill Fumigators to Sana Curtainfire in the Ban'Thallow Barrow Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28711] = { id = 28711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Borean Tundra!", description = "All able bodied members of the Horde are hereby ordered to report to the Warsong Recruitment Officer at Warsong Hold.\n\nThe Warsong Offensive needs your help to overcome the continued threat from the undead Scourge.\n\nTake the zeppelin to Warsong Hold from Orgrimmar's western zeppelin tower and present yourself to the recruitment officer.\n\nDestiny calls!", completion = "The Warsong Offensive could use more like you, {class}.", objectives = "Report to the Warsong Recruitment Officer at Warsong Hold in Borean Tundra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28712] = { id = 28712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enter the Dragon Queen", description = "Hello, {race}. I wish we could meet in more favorable circumstances. The world hangs by a thread, and all that the Titans have wrought may be in jeopardy.\n\nIt saddens me greatly, but my judgment is final. Deathwing - the horrific creature that was once the Earth Warder and once my friend - must be destroyed.\n\nI have prepared a site atop the Highlands, to the west of the Vermillion Redoubt, where I can bring about his end. Seek out the Circle of Life and speak with Lirastrasza within. I will join you there.", completion = "Hello again, {race}. I hear you were instrumental in our push toward Grim Batol - thank you!\n\nAlexstrasza has sanctified this ground in the hopes of luring Deathwing here. She'll perform a ceremony to lure him out... and then destroy him within this sacred circle.\n\nLet's hope her plan works.", objectives = "Seek out Lirastrasza at the Circle of Life in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28713] = { id = 28713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Balance of Nature", description = "Greetings, {name}. I am Ilthalaine. My purpose in Shadowglen is to train young {class}s like you and to ensure that the balance of nature is maintained.\n\nThe spring rains were particularly heavy this year, causing some of the forest's beasts to flourish while others suffered. Unfortunately, the nightsaber numbers grew too large, and they will devastate the other populations if they are not culled.\n\nJourney forth, young {class}, and thin saber populations so that nature's harmony will be preserved.", progress = "There is still work to be done, {name}. Return to me once you have thinned the nightsaber population.", completion = "You performed your duties well, {name}.", objectives = "Kill 6 Young Nightsabers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28714] = { id = 28714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Moss Corruption", description = "You seem to know what you're doing. Perhaps I can task you with something a little more important.\n\nAs you may well know, the corruption in Teldrassil was supposedly wiped away. Yet something lingers. The creatures have not calmed and all manner of problems still plague us.\n\nI need you to deal with the grellkin that have gathered to the west, and while you're there, I want you to search them for fel moss. This will help me determine from where this continuing corruption stems.", progress = "Satisfy my suspicions, {name}. Bring to me fel moss from the grellkin.", completion = "Your service to the creatures of Shadowglen is worthy of reward, {name}.\n\nYou confirmed my fears, however. The grellkin are still tainted by fel moss, despite Teldrassil's blessing. Something sinister remains within the tree. I can only hope that the Gnarlpine tribe of furbolgs are free of the corruption, or we are still in grave danger.\n\nI will look into this further and contact those who might be of aid. Thank you, {class}.", objectives = "Collect 6 Fel Moss from the grellkin to the west of Ilthalaine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28715] = { id = 28715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonic Thieves", description = "Vicious little grell! They've been stealing from our foodstores again.\n\nIf you wouldn't mind lending a hand, they are sure to have my stolen bags within their camps to the west. I would be glad to reward you if you can bring them back to me.", progress = "I don't have any spare supplies for my customers until my stolen goods are recovered. Have you had any luck?", completion = "Elune be praised! And you as well, young {class}.\n\nThere are many young night elves in need of these, but I'd be more than happy to give you one of the bags as a reward. I'm sure it will come in handy.\n\nSafe travels to you.", objectives = "Recover Melithar's Stolen Bags near the grellkin to the west.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28716] = { id = 28716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Twilight Highlands!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to the throne room in Stormwind Keep.\n\nKing Wrynn requires a trustworthy and proven hero for a mission of the utmost importance.\n\nStormwind Keep can be found in the eastern portion of Stormwind City.\n\nAnyone willing may report to Grand Admiral Jes-Tereth for briefing. For the glory and honor of the Alliance!", completion = "We are pleased that you have answered our summons, {class}.", objectives = "Speak with Grand Admiral Jes-Tereth at Stormwind Keep in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28717] = { id = 28717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Twilight Highlands!", description = "All able-bodied members of the Horde are hereby ordered to report to High Overlord Saurfang in Grommash Hold.\n\nHigh Overlord Saurfang requires your help to prepare for the glorious assault on the Twilight Highlands and our dual enemies, the Alliance and Twilight's Hammer.\n\nMeet with him in Grommash Hold at the center of Orgrimmar's Valley of Strength.\n\nDestiny calls!", completion = "Soon, the assault on the Twilight Highlands will begin, and I intend for you to be a part of it.", objectives = "Report to High Overlord Saurfang at Grommash Hold in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28718] = { id = 28718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where There's Smoke, There's Delicious Meat", description = "Say there, {class}... do you like meat?  Even better, do you like money?\n\nI got a second cousin who's making a killing in the frozen meats business.  He's set up a smoking pit up north, and he's looking for help hunting all the dangerous beasties that always tend to taste so good.\n\nCarnivores pay well, friend.  I'm too heavily invested here in this barrow den - what was I thinking? - so I might as well pass the tip on to a helpful {race} like yourself.\n\nHis name's Jez.  Head northeast, and look for the smoke!", completion = "Look around you; you're looking at the largest goblin-owned hunting reserve in Kalimdor! I've got the licenses to shoot and eat everything that walks on the snow from here to Everlook... and lemme tell you, they're good eatin'!", objectives = "Find Jez Goodgrub at Goodgrub Smoking Pit in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28719] = { id = 28719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Gamy", description = "Many find the meat of the Shardtooth bears to be too gamy for their taste. I disagree, though I'm not one to judge the tastes of others.\n\nThe Shardtooth Maulers, however - their brown-furred cousins, to the south - have much more tender flesh, particularly in their paws. And I've heard that the snout is also considered a delicacy.\n\nContinue your hunt, {name}. Let's see if you can bag those maulers for ol' Francis.", completion = "<Francis smacks his lips.>\n\nYou've got to try some of this, {name}.  These maulers are perfectly tenderized... possibly because of the pummeling you delivered.", objectives = "Kill 15 Shardtooth Maulers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28720] = { id = 28720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Find of Significance" }
quests[28721] = { id = 28721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walk A Mile In Their Shoes", description = "We have sent at least 3 different recon groups to investigate Farson Hold in the last few weeks.  Sadly, not one of them has returned back with any info.\n\nAt this point, all we can hope is that they are being held alive as prisoners.  I need you to infiltrate the keep and help get our soldiers back.  This won't be easy {name}, but if anyone can help us, it's you.", completion = "You saved our men!  No words can express our gratitude {name}.", objectives = "Escort a Farson Keep Prisoner to safety. The hold is located on the northern tip of the island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28722] = { id = 28722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yetiphobia", description = "It's all ready, {name}!\n\nNow, I told my friend Legacki that I have a surprise for her. This is where you come in!\n\nI'm going to give you my mechanical yeti, and you'll get the honor of using it to surprise her. She's just on the other side of Everlook, near the inn.\n\nGo up to her and turn the yeti on... I'll be watching from here!", progress = "She'll never expect it!", completion = "Hah! She'll think twice before making fun of my ideas again!\n\nThanks for your help, {name}. I couldn't have had so much fun without you!", objectives = "Scare Legacki with Umi's Mechanical Yeti.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28723] = { id = 28723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priestess of the Moon", description = "Perhaps you'd be willing to aid us in further pursuing the corruption haunting Shadowglen.\n\nDentaria Silverglade, Priestess of the Moon, has offered to aid us. You should find her between the two pools just north of our great tree. Circle around the tree to reach her and offer her any help that you can, young {class}.", completion = "It is good that you've come. It seems your training progresses quickly.", objectives = "Speak to Dentaria Silverglade between the two pools in the center of Shadowglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28724] = { id = 28724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iverron's Antidote", description = "Our friend Iverron has fallen to poison from the nearby webwood spiders. I can tend to him to keep his state from deteriorating, but I need someone to gather an ingredient to prepare him an antidote.\n\nAll around the ponds you should find Moonpetal Lilies. These flowers have great healing properties, and I can use them with the ingredients I already have to restore Iverron to better health.\n\nWould you gather them for me?  There should be many just in sight of here, near the water's edge.", progress = "Our dear friend is not doing well, even with my mending. Have you brought the supplies I require?", completion = "These will do perfectly. Thank you, {name}. Your swiftness is appreciated.", objectives = "Collect 7 Moonpetal Lilies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28725] = { id = 28725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Woodland Protector", description = "I must ask something more dangerous of you. Strange news has traveled to me through the whisperings of the forest spirits. The mysterious woodland protector, Tarindrella, has returned to Shadowglen again.\n\nThe dryad's presence has not been felt in the forests since before the blessing of Teldrassil. Something is surely amiss if she has journeyed back to this land.\n\nSeek out Tarindrella in the Shadowthread cave to the north. It is dangerous, but we will be prepared with this antidote just in case.", completion = "I see you found me, young {race}.  Dentaria was wise to have sent you.", objectives = "Seek out the dryad known as Tarindrella within the Shadowthread Cave at the northern end of Shadowglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28726] = { id = 28726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Webwood Corruption", description = "I'd hoped to never return to Teldrassil for such grim business. I'd hoped that its corruption had been wiped away completely.  Something foul lingers.\n\nThese spiders suffer much more deeply from the corruption than the other nearby wildlife. They are becoming a danger to your people and a danger to the forest. We must thin their numbers, but more importantly, we need to find the source of the corruption that plagues them.\n\nI will come with you and aid you in this.", progress = "This is grim work. It pains me to have to inflict such violence on creature of the forest, corrupt or not.", completion = "This corruption these spiders suffer from is not simply surface deep. It cannot be magic or subtle malintent. It is bred into them.\n\nIt seems our next task is clear.", objectives = "Kill 12 Webwood Spiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28727] = { id = 28727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile Touch", description = "If these spiders are born with corruption in their veins, then their broodmother must be at the root of this evil.\n\nLet us make our way to the far north end of the cave and seek out Githyiss the Vile. The answers we seek lie with her.", progress = "I adore these forests. I want to see the corruption purged from them completely. When next I return, I want to do so with a lighter heart.", completion = "Githyiss and her brood were being corrupted by this totem. This is a furbolg totem.\n\nThis is very troubling indeed. This means the Gnarlpine are still a danger to these forests. We let our guard down too soon.", objectives = "Kill Githyiss the Vile at the northen end of the Shadowthread Cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28728] = { id = 28728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of Things to Come", description = "I will pursue the trail of the Gnarlpine and track this corruption to its source. If you ever encounter Athridas Bearmantle in Dolanaar, he knows intimately of the problems that plague this forest, and he can direct you on how to help further.\n\nI'm sure we will meet again with time. Perhaps you can aid me in dealing with the source of this corruption once I locate it. For now, I will take you back to Dentaria so that you may finish your training. Thank you for all that you have done, {name}.", completion = "You've returned! It's good to see you. It seems you've dealt with the source of much of the corruption in Shadowglen.\n\nTeldrassil still suffers and will need attention, be we can afford a moment or two for you to finish your training here in Shadowglen.", objectives = "Speak to Dentaria Silverglade between the pools in northern Shadowglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28729] = { id = 28729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassil: Crown of Azeroth", description = "As part of a ritual to complete your training here in Shadowglen, you must learn about our recent history.\n\nThere is a task you must perform. Go to the moonwell to our northeast and retrieve a phial of its water. While there, you will witness a glimpse of our magics and learn of our past.\n\nWhen you are done there, bring the water back to me, and I will direct you further.", progress = "Our recent history is fraught with strife and violence. There is still much with which we must come to terms.", completion = "Well done, {name}. You have one task left for you before you depart Shadowglen for the open wilds of Teldrassil.", objectives = "Fill the Crystal Phial at the moonwell in northeast Shadowglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28730] = { id = 28730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Waters", description = "Tenaron Stormgrip oversees all that happens in this glade. He presides at the top of Aldrassil.\n\nIf you look to your south, you will see the underside of the ramp that leads up to him. Ascend this ramp and complete your training.\n\nIt was wonderful to have met you, {name}. I swell with pride knowing that among young night elves, there are some so selfless and full of life as you are. You will do great things for our people. You will do great things for this world.\n\nUntil we meet again.", progress = "The moonwells hold the waters of the Well of Eternity, the ancient source of magic that has wrought so many horrors upon our world.\n\nThe druids take advantage of its properties, the Sentinels revere the wells as shrines to Elune, and now even the returning Highborne look to the wells longingly.", completion = "So you have heard the first part of the aftermath of the Battle of Mount Hyjal. There is much more for you to learn and the task you have begun here will continue through the rest of your journey through Teldrassil and into Darnassus.", objectives = "Bring the filled crystal phial to Tenaron Stormgrip at the top of Aldrassil in Shadowglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28731] = { id = 28731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassil: Passing Awareness", description = "While there is more I could speak to you of the moonwells and of Teldrassil, I must send you along. Corithras Moonrage will be expecting you. I have poured the phial of water you brought to me into this vessel to bring to him.\n\nSeek out Corithras. You will find him at the moonwell in Dolanaar. Follow the road south from Aldrassil out of Shadowglen, and continue to follow the cobblestones as the road turns west.\n\nMind you stay on the road though, {name}. There are dangerous beasts in the forests of late.", progress = "Greetings, {class}. For what purpose do I owe the pleasure of our meeting?", completion = "Ah, I see. You were sent by Tenaron. Well then, it would seem we have much to talk about, much to do.\n\nBefore we get to the task at hand, you should take in the lesson of this moonwell.", objectives = "Bring the Partially Filled Vessel to Corithras Moonrage in Dolanaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28732] = { id = 28732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Can Only Mean One Thing...", description = "Raz and I were enlisted by the Guardians of Hyjal to investigate the re-emergence of Ragnaros into our world. Let me go ahead and confirm that he is back and he is angry! We also have evidence that these Twilight's Hammer cultists are moving elementals from here to Blackrock Caverns, over in the Eastern Kingdoms.\n\nRaz and I were about to head over there to investigate. We've got room for another in the mole machine if you're interested. Just meet us on the inside and we'll begin our journey.", completion = "Oh dear, Raz has been captured! As soon as we entered a dozen cultists and some big fat ogre jumped us. I ran while I Raz tried to fight them off. We need to save him, {name}!", objectives = "Take Pip's Mole Machine to Blackrock Mountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28733] = { id = 28733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Botany", description = "HELP! HELP! Crazed undead are attacking my farm! That psycho warden over at the Sludge Fields is probably responsible for this mess. Help me fight off the zombies!", completion = "PHEW! That was close! You're a real natural with these plants, {class}. You know, I brought the seeds here with me from Lost Isles. I figure once I get them all figured out I'll make a fortune in the deadly flower business!\n\nWha... LOOK! MORE ARE COMING!", objectives = "Survive a Massive Wave of Zombies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28734] = { id = 28734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Favor for Melithar", description = "You should speak with Melithar. I believe he had some troubles with the grell already.\n\nI expect he can offer you a well needed place to store more of your goods should you aid him.", completion = "Ilthalaine sent you? He was wise to do so. I am indeed in need of help.", objectives = "Speak to Melithar Staghelm in Shadowglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28735] = { id = 28735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Chamber of Incineration!", description = "It was an ambush, {name}! As soon as we walked in a super-fat ogre named Rom'ogg Bonecrusher attacked us! Raz bravely defended me while I ran off to hide. I watched as they beat him unconscious and then dragged him to a place the fat one called the \"Chamber of Incineration.\" I think it's just down the hall across the bridge.\n\nI'm too scared to go any further. Take my all-purpose diving helm and search for Raz. I'll communicate with you through the helm.\n\nAnd if you find that ogre, kill him!", progress = "<Pip's helm crackles with static.>", completion = "<Finkle's helm crackles with static.>\n\nRAZ! What have they done to him!? FOLLOW HIM!", objectives = "Kill Rom'ogg Bonecrusher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28736] = { id = 28736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire From the Sky", description = "The remnants of Schnottz's organization persist here on the Maker's Ascent, making the region deadly to any who draw near.\n\nThere's plenty of ammunition, but without a good spotter, I'm just firing blind.\n\nHop in and give me a hand here. Those soldiers won't know what hit them!", progress = "It's a target-rich environment, {class}.", completion = "The enemy on Maker's Ascent remain a threat, but with your help we've dealt a serious blow to their numbers and their morale.", objectives = "Board the Confiscated Artillery and use it to kill 100 Schnottz Infantrymen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28737] = { id = 28737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Is This Place?", description = "<Pip's helm gives you a slight jolt.>\n\nWhat is this place? It looks like they're doing something terrible to that nether dragon. The energy is being siphoned from the creature into that lady! We need to stop this ritual!\n\nKill Corla to get past this hall!", completion = "<Finkle's helm crackles with static.>\n\nWe haven't got much time. Raz looked injured. If we get to him in time there might be a chance that I can turn him back into a regular orc!\n\n<You feel a sharp pain in the back of your head and hear the jingling of coins.>\n\nSorry about that. I figured I'd send through some gold - for your troubles and all that...", objectives = "Kill Corla, Herald of Twilight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28738] = { id = 28738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Forge", description = "<Pip's helm hums with energy.>\n\nDamn it! Raz won't stop! It's as if he were possessed with a burning vengeance for all things Twilight! It looks like if we're going to get past this room and catch up with Raz we'll need to take out the Twilight armorer, Karsh Steelbender. Kill him quick, {name}.", progress = "<Pip's helm crackles with static.>", completion = "<Finkle's helm crackles with static.>\n\nThat should put a stop to their armory - at least for now.\n\nRaz ran off across the ramp on the other side of the forge. GO GO GO!", objectives = "Kill Karsh Steelbender.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28739] = { id = 28739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Night Elf Class Skill Tracker Quest" }
quests[28740] = { id = 28740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do My Eyes Deceive Me?", description = "<Pip's helm explodes with the sound of a loud girlish scream.>\n\nIT CAN'T BE! I... I was stuck inside one of those beasts for the better part of a month. Yes, literally stuck inside its stomach. If it weren't for my suit and the all-purpose helm I'd have died a fiery death! And look at that, it's had a litter of pups!\n\nY... You gotta stop that thing, {name}! We can't let it or its pups make it out of here alive!", completion = "<Finkle's helm crackles with static.>\n\nPhew... That's one less thing I'll need to worry about if we ever make it out of this place.", objectives = "Kill Beauty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
